INSERT INTO exercise (exercise_code, name_ko, name_en, exercise_type, primary_muscle, movement_pattern, minimum_experience_level, baseline_record_type, guide, video_url) VALUES ('EX_CHEST_STANDARD_PUSHUP', '스탠다드 푸시업', 'Standard Push-up', 'STRENGTH', 'CHEST', 'HORIZONTAL_PUSH', 'BEGINNER', 'REPS_SETS', '손을 어깨너비보다 약간 넓게 짚고 머리부터 발끝까지 일직선을 유지해주세요.\n팔꿈치를 몸통에서 약 45도 벌리며 가슴을 바닥 쪽으로 내렸다가 밀어 올려주세요.\n허리가 꺾이거나 엉덩이가 처지지 않도록 주의해주세요.', 'https://www.youtube.com/watch?v=Env8gAr_QnE') ON DUPLICATE KEY UPDATE name_ko=VALUES(name_ko), name_en=VALUES(name_en), exercise_type=VALUES(exercise_type), primary_muscle=VALUES(primary_muscle), movement_pattern=VALUES(movement_pattern), minimum_experience_level=VALUES(minimum_experience_level), baseline_record_type=VALUES(baseline_record_type), guide=VALUES(guide), video_url=VALUES(video_url);
INSERT INTO exercise (exercise_code, name_ko, name_en, exercise_type, primary_muscle, movement_pattern, minimum_experience_level, baseline_record_type, guide, video_url) VALUES ('EX_CHEST_INCLINE_PUSHUP', '인클라인 푸시업', 'Incline Push-up', 'STRENGTH', 'CHEST', 'HORIZONTAL_PUSH', 'FIRST_TIME', 'REPS_SETS', '안정적인 벤치나 지지대에 손을 어깨너비보다 약간 넓게 짚어주세요.\n몸을 일직선으로 유지하며 가슴을 지지대 쪽으로 내렸다가 밀어 올려주세요.\n어깨가 올라가거나 허리가 아래로 처지지 않도록 주의해주세요.', 'https://www.youtube.com/watch?v=yAbg3_pJKvw') ON DUPLICATE KEY UPDATE name_ko=VALUES(name_ko), name_en=VALUES(name_en), exercise_type=VALUES(exercise_type), primary_muscle=VALUES(primary_muscle), movement_pattern=VALUES(movement_pattern), minimum_experience_level=VALUES(minimum_experience_level), baseline_record_type=VALUES(baseline_record_type), guide=VALUES(guide), video_url=VALUES(video_url);
INSERT INTO exercise (exercise_code, name_ko, name_en, exercise_type, primary_muscle, movement_pattern, minimum_experience_level, baseline_record_type, guide, video_url) VALUES ('EX_CHEST_DECLINE_PUSHUP', '디클라인 푸시업', 'Decline Push-up', 'STRENGTH', 'CHEST', 'HORIZONTAL_PUSH', 'INTERMEDIATE', 'REPS_SETS', '발을 안정적인 벤치 위에 올리고 손은 어깨너비보다 약간 넓게 짚어주세요.\n몸을 일직선으로 유지하며 가슴을 바닥 쪽으로 내렸다가 밀어 올려주세요.\n허리를 과하게 꺾거나 고개를 아래로 떨어뜨리지 않도록 주의해주세요.', 'https://www.youtube.com/watch?v=QBlYp-EwHlo') ON DUPLICATE KEY UPDATE name_ko=VALUES(name_ko), name_en=VALUES(name_en), exercise_type=VALUES(exercise_type), primary_muscle=VALUES(primary_muscle), movement_pattern=VALUES(movement_pattern), minimum_experience_level=VALUES(minimum_experience_level), baseline_record_type=VALUES(baseline_record_type), guide=VALUES(guide), video_url=VALUES(video_url);
INSERT INTO exercise (exercise_code, name_ko, name_en, exercise_type, primary_muscle, movement_pattern, minimum_experience_level, baseline_record_type, guide, video_url) VALUES ('EX_CHEST_WIDE_PUSHUP', '와이드 푸시업', 'Wide Push-up', 'STRENGTH', 'CHEST', 'HORIZONTAL_PUSH', 'BEGINNER', 'REPS_SETS', '손을 어깨너비보다 넓게 벌리고 몸을 일직선으로 유지해주세요.\n팔꿈치를 자연스럽게 굽혀 가슴을 바닥 쪽으로 내렸다가 밀어 올려주세요.\n손을 지나치게 넓게 벌리거나 어깨에 무리가 가지 않도록 주의해주세요.', 'https://www.youtube.com/watch?v=UFa702F5WnY') ON DUPLICATE KEY UPDATE name_ko=VALUES(name_ko), name_en=VALUES(name_en), exercise_type=VALUES(exercise_type), primary_muscle=VALUES(primary_muscle), movement_pattern=VALUES(movement_pattern), minimum_experience_level=VALUES(minimum_experience_level), baseline_record_type=VALUES(baseline_record_type), guide=VALUES(guide), video_url=VALUES(video_url);
INSERT INTO exercise (exercise_code, name_ko, name_en, exercise_type, primary_muscle, movement_pattern, minimum_experience_level, baseline_record_type, guide, video_url) VALUES ('EX_CHEST_DIAMOND_PUSHUP', '다이아몬드 푸시업', 'Diamond Push-up', 'STRENGTH', 'CHEST', 'HORIZONTAL_PUSH', 'INTERMEDIATE', 'REPS_SETS', '가슴 아래에 양손을 모아 엄지와 검지로 마름모 모양을 만들어주세요.\n팔꿈치를 몸통 가까이 유지하며 가슴을 손 쪽으로 내렸다가 밀어 올려주세요.\n손목에 통증이 생기지 않도록 주의하고 몸통이 흔들리지 않게 유지해주세요.', 'https://www.youtube.com/watch?v=K8bKxVcwjrk') ON DUPLICATE KEY UPDATE name_ko=VALUES(name_ko), name_en=VALUES(name_en), exercise_type=VALUES(exercise_type), primary_muscle=VALUES(primary_muscle), movement_pattern=VALUES(movement_pattern), minimum_experience_level=VALUES(minimum_experience_level), baseline_record_type=VALUES(baseline_record_type), guide=VALUES(guide), video_url=VALUES(video_url);
INSERT INTO exercise (exercise_code, name_ko, name_en, exercise_type, primary_muscle, movement_pattern, minimum_experience_level, baseline_record_type, guide, video_url) VALUES ('EX_TRICEPS_BENCH_DIPS', '벤치 딥스', 'Bench Dips', 'STRENGTH', 'TRICEPS', 'ELBOW_EXTENSION', 'BEGINNER', 'REPS_SETS', '안정적인 벤치 끝에 양손을 짚고 엉덩이를 벤치 앞으로 이동시켜주세요.\n몸을 벤치 가까이에 유지하며 팔꿈치를 굽혀 내려갔다가 다시 밀어 올려주세요.\n어깨가 과도하게 뒤로 젖혀지지 않도록 내려가는 깊이를 조절해주세요.', 'https://www.youtube.com/watch?v=qrS6aa0aQ9I') ON DUPLICATE KEY UPDATE name_ko=VALUES(name_ko), name_en=VALUES(name_en), exercise_type=VALUES(exercise_type), primary_muscle=VALUES(primary_muscle), movement_pattern=VALUES(movement_pattern), minimum_experience_level=VALUES(minimum_experience_level), baseline_record_type=VALUES(baseline_record_type), guide=VALUES(guide), video_url=VALUES(video_url);
INSERT INTO exercise (exercise_code, name_ko, name_en, exercise_type, primary_muscle, movement_pattern, minimum_experience_level, baseline_record_type, guide, video_url) VALUES ('EX_CHEST_DB_BENCH_PRESS', '덤벨 벤치 프레스', 'Dumbbell Bench Press', 'STRENGTH', 'CHEST', 'HORIZONTAL_PUSH', 'BEGINNER', 'WEIGHT_REPS_SETS', '벤치에 누워 양발을 바닥에 고정하고 덤벨을 가슴 양옆에 위치시켜주세요.\n손목을 곧게 유지하며 덤벨을 위로 밀어 올린 뒤 천천히 내려주세요.\n팔꿈치를 지나치게 벌리거나 허리를 과하게 꺾지 않도록 주의해주세요.', 'https://www.youtube.com/watch?v=AduT4Eq-iP0') ON DUPLICATE KEY UPDATE name_ko=VALUES(name_ko), name_en=VALUES(name_en), exercise_type=VALUES(exercise_type), primary_muscle=VALUES(primary_muscle), movement_pattern=VALUES(movement_pattern), minimum_experience_level=VALUES(minimum_experience_level), baseline_record_type=VALUES(baseline_record_type), guide=VALUES(guide), video_url=VALUES(video_url);
INSERT INTO exercise (exercise_code, name_ko, name_en, exercise_type, primary_muscle, movement_pattern, minimum_experience_level, baseline_record_type, guide, video_url) VALUES ('EX_CHEST_DB_FLY', '덤벨 플라이', 'Dumbbell Fly', 'STRENGTH', 'CHEST', 'HORIZONTAL_PUSH', 'INTERMEDIATE', 'WEIGHT_REPS_SETS', '벤치에 누워 덤벨을 가슴 위로 들고 팔꿈치를 살짝 굽혀주세요.\n팔을 양옆으로 천천히 벌렸다가 가슴 근육을 사용해 다시 모아주세요.\n어깨에 무리가 가지 않도록 팔을 지나치게 낮추지 말아주세요.', 'https://www.youtube.com/watch?v=Nhvz9EzdJ4U') ON DUPLICATE KEY UPDATE name_ko=VALUES(name_ko), name_en=VALUES(name_en), exercise_type=VALUES(exercise_type), primary_muscle=VALUES(primary_muscle), movement_pattern=VALUES(movement_pattern), minimum_experience_level=VALUES(minimum_experience_level), baseline_record_type=VALUES(baseline_record_type), guide=VALUES(guide), video_url=VALUES(video_url);
INSERT INTO exercise (exercise_code, name_ko, name_en, exercise_type, primary_muscle, movement_pattern, minimum_experience_level, baseline_record_type, guide, video_url) VALUES ('EX_CHEST_BAND_PRESS', '밴드 체스트 프레스', 'Band Chest Press', 'STRENGTH', 'CHEST', 'HORIZONTAL_PUSH', 'FIRST_TIME', 'REPS_SETS', '밴드를 등 뒤에 걸거나 가슴 높이의 안정적인 지점에 고정하고 양손으로 잡아주세요.\n가슴을 편 상태에서 양손을 앞으로 밀어냈다가 천천히 돌아와 주세요.\n밴드가 빠지지 않도록 고정 상태를 확인하고 허리가 꺾이지 않게 유지해주세요.', 'https://www.youtube.com/watch?v=po8JwkjexbU') ON DUPLICATE KEY UPDATE name_ko=VALUES(name_ko), name_en=VALUES(name_en), exercise_type=VALUES(exercise_type), primary_muscle=VALUES(primary_muscle), movement_pattern=VALUES(movement_pattern), minimum_experience_level=VALUES(minimum_experience_level), baseline_record_type=VALUES(baseline_record_type), guide=VALUES(guide), video_url=VALUES(video_url);
INSERT INTO exercise (exercise_code, name_ko, name_en, exercise_type, primary_muscle, movement_pattern, minimum_experience_level, baseline_record_type, guide, video_url) VALUES ('EX_CHEST_BB_BENCH_PRESS', '바벨 벤치 프레스', 'Barbell Bench Press', 'STRENGTH', 'CHEST', 'HORIZONTAL_PUSH', 'INTERMEDIATE', 'WEIGHT_REPS_SETS', '벤치에 누워 양발을 바닥에 고정하고 바벨을 어깨너비보다 약간 넓게 잡아주세요.\n바벨을 가슴 아래쪽으로 천천히 내렸다가 밀어 올려주세요.\n손목이 뒤로 꺾이거나 엉덩이가 벤치에서 들리지 않도록 주의해주세요.', 'https://www.youtube.com/watch?v=CjHIKDQ4RQo') ON DUPLICATE KEY UPDATE name_ko=VALUES(name_ko), name_en=VALUES(name_en), exercise_type=VALUES(exercise_type), primary_muscle=VALUES(primary_muscle), movement_pattern=VALUES(movement_pattern), minimum_experience_level=VALUES(minimum_experience_level), baseline_record_type=VALUES(baseline_record_type), guide=VALUES(guide), video_url=VALUES(video_url);
INSERT INTO exercise (exercise_code, name_ko, name_en, exercise_type, primary_muscle, movement_pattern, minimum_experience_level, baseline_record_type, guide, video_url) VALUES ('EX_CHEST_INCLINE_BB_PRESS', '인클라인 바벨 프레스', 'Incline Barbell Press', 'STRENGTH', 'CHEST', 'HORIZONTAL_PUSH', 'INTERMEDIATE', 'WEIGHT_REPS_SETS', '벤치 각도를 약 15~30도로 설정하고 바벨을 어깨너비보다 약간 넓게 잡아주세요.\n바벨을 윗가슴 쪽으로 천천히 내렸다가 밀어 올려주세요.\n어깨가 과도하게 올라가거나 허리가 지나치게 꺾이지 않도록 주의해주세요.', 'https://www.youtube.com/watch?v=2jFFCy8JBU8') ON DUPLICATE KEY UPDATE name_ko=VALUES(name_ko), name_en=VALUES(name_en), exercise_type=VALUES(exercise_type), primary_muscle=VALUES(primary_muscle), movement_pattern=VALUES(movement_pattern), minimum_experience_level=VALUES(minimum_experience_level), baseline_record_type=VALUES(baseline_record_type), guide=VALUES(guide), video_url=VALUES(video_url);
INSERT INTO exercise (exercise_code, name_ko, name_en, exercise_type, primary_muscle, movement_pattern, minimum_experience_level, baseline_record_type, guide, video_url) VALUES ('EX_CHEST_PRESS_MACHINE', '체스트 프레스 머신', 'Chest Press Machine', 'STRENGTH', 'CHEST', 'HORIZONTAL_PUSH', 'FIRST_TIME', 'WEIGHT_REPS_SETS', '손잡이가 가슴 높이에 오도록 좌석을 조절하고 등과 엉덩이를 등받이에 붙여주세요.\n가슴을 편 상태에서 손잡이를 앞으로 밀어낸 뒤 천천히 돌아와 주세요.\n어깨가 들리거나 팔꿈치가 과도하게 펴지지 않도록 주의해주세요.', 'https://www.youtube.com/watch?v=CIykDiF4sfg') ON DUPLICATE KEY UPDATE name_ko=VALUES(name_ko), name_en=VALUES(name_en), exercise_type=VALUES(exercise_type), primary_muscle=VALUES(primary_muscle), movement_pattern=VALUES(movement_pattern), minimum_experience_level=VALUES(minimum_experience_level), baseline_record_type=VALUES(baseline_record_type), guide=VALUES(guide), video_url=VALUES(video_url);
INSERT INTO exercise (exercise_code, name_ko, name_en, exercise_type, primary_muscle, movement_pattern, minimum_experience_level, baseline_record_type, guide, video_url) VALUES ('EX_CHEST_PEC_DECK_FLY', '펙덱 플라이 머신', 'Pec Deck Fly Machine', 'STRENGTH', 'CHEST', 'HORIZONTAL_PUSH', 'FIRST_TIME', 'WEIGHT_REPS_SETS', '손잡이가 가슴 높이에 오도록 좌석을 조절하고 등을 등받이에 붙여주세요.\n팔꿈치를 살짝 굽힌 상태에서 양팔을 가슴 앞으로 모았다가 천천히 벌려주세요.\n팔을 지나치게 뒤로 벌리거나 어깨가 올라가지 않도록 주의해주세요.', 'https://www.youtube.com/watch?v=eGjt4lk6g34') ON DUPLICATE KEY UPDATE name_ko=VALUES(name_ko), name_en=VALUES(name_en), exercise_type=VALUES(exercise_type), primary_muscle=VALUES(primary_muscle), movement_pattern=VALUES(movement_pattern), minimum_experience_level=VALUES(minimum_experience_level), baseline_record_type=VALUES(baseline_record_type), guide=VALUES(guide), video_url=VALUES(video_url);
INSERT INTO exercise (exercise_code, name_ko, name_en, exercise_type, primary_muscle, movement_pattern, minimum_experience_level, baseline_record_type, guide, video_url) VALUES ('EX_CHEST_CABLE_CROSSOVER', '케이블 크로스오버', 'Cable Crossover', 'STRENGTH', 'CHEST', 'HORIZONTAL_PUSH', 'BEGINNER', 'WEIGHT_REPS_SETS', '케이블 손잡이를 양손에 잡고 한 발을 앞으로 내딛어 상체를 살짝 기울여주세요.\n팔꿈치를 약간 굽힌 상태에서 양손을 가슴 앞쪽으로 모았다가 천천히 벌려주세요.\n반동을 사용하거나 어깨가 과도하게 뒤로 젖혀지지 않도록 주의해주세요.', 'https://www.youtube.com/watch?v=QcTcWpkn_bw') ON DUPLICATE KEY UPDATE name_ko=VALUES(name_ko), name_en=VALUES(name_en), exercise_type=VALUES(exercise_type), primary_muscle=VALUES(primary_muscle), movement_pattern=VALUES(movement_pattern), minimum_experience_level=VALUES(minimum_experience_level), baseline_record_type=VALUES(baseline_record_type), guide=VALUES(guide), video_url=VALUES(video_url);
INSERT INTO exercise (exercise_code, name_ko, name_en, exercise_type, primary_muscle, movement_pattern, minimum_experience_level, baseline_record_type, guide, video_url) VALUES ('EX_BACK_PULLUP', '풀업', 'Pull-up', 'STRENGTH', 'BACK', 'VERTICAL_PULL', 'INTERMEDIATE', 'REPS_SETS', '철봉을 어깨너비보다 약간 넓게 손등이 얼굴을 향하도록 잡아주세요.\n어깨를 아래로 내리며 팔꿈치를 몸통 쪽으로 당겨 턱을 철봉 높이까지 올려주세요.\n몸을 흔들거나 반동을 사용하지 말고 천천히 내려와 주세요.', 'https://www.youtube.com/watch?v=PHdHnZcbsB8') ON DUPLICATE KEY UPDATE name_ko=VALUES(name_ko), name_en=VALUES(name_en), exercise_type=VALUES(exercise_type), primary_muscle=VALUES(primary_muscle), movement_pattern=VALUES(movement_pattern), minimum_experience_level=VALUES(minimum_experience_level), baseline_record_type=VALUES(baseline_record_type), guide=VALUES(guide), video_url=VALUES(video_url);
INSERT INTO exercise (exercise_code, name_ko, name_en, exercise_type, primary_muscle, movement_pattern, minimum_experience_level, baseline_record_type, guide, video_url) VALUES ('EX_BACK_CHINUP', '친업', 'Chin-up', 'STRENGTH', 'BACK', 'VERTICAL_PULL', 'INTERMEDIATE', 'REPS_SETS', '철봉을 어깨너비 정도로 손바닥이 얼굴을 향하도록 잡아주세요.\n팔꿈치를 몸통 가까이 당기며 턱을 철봉 위로 올렸다가 천천히 내려와 주세요.\n어깨가 과도하게 올라가거나 몸이 앞뒤로 흔들리지 않도록 주의해주세요.', 'https://www.youtube.com/watch?v=2S8jyfcnBmc') ON DUPLICATE KEY UPDATE name_ko=VALUES(name_ko), name_en=VALUES(name_en), exercise_type=VALUES(exercise_type), primary_muscle=VALUES(primary_muscle), movement_pattern=VALUES(movement_pattern), minimum_experience_level=VALUES(minimum_experience_level), baseline_record_type=VALUES(baseline_record_type), guide=VALUES(guide), video_url=VALUES(video_url);
INSERT INTO exercise (exercise_code, name_ko, name_en, exercise_type, primary_muscle, movement_pattern, minimum_experience_level, baseline_record_type, guide, video_url) VALUES ('EX_BACK_SUPERMAN_HOLD', '슈퍼맨 홀드', 'Superman Hold', 'STRENGTH', 'BACK', 'HINGE', 'FIRST_TIME', 'REPS_SETS', '배를 바닥에 대고 엎드려 양팔을 머리 위로 뻗고 다리를 곧게 펴주세요.\n팔과 다리를 바닥에서 조금 들어 올린 상태를 잠시 유지한 뒤 천천히 내려주세요.\n고개를 과하게 들거나 허리를 심하게 꺾지 않도록 주의해주세요.', 'https://www.youtube.com/watch?v=kTMBsUwEGPM') ON DUPLICATE KEY UPDATE name_ko=VALUES(name_ko), name_en=VALUES(name_en), exercise_type=VALUES(exercise_type), primary_muscle=VALUES(primary_muscle), movement_pattern=VALUES(movement_pattern), minimum_experience_level=VALUES(minimum_experience_level), baseline_record_type=VALUES(baseline_record_type), guide=VALUES(guide), video_url=VALUES(video_url);
INSERT INTO exercise (exercise_code, name_ko, name_en, exercise_type, primary_muscle, movement_pattern, minimum_experience_level, baseline_record_type, guide, video_url) VALUES ('EX_BACK_YTW_RAISE', 'Y-T-W 레이즈', 'Y-T-W Raise', 'STRENGTH', 'BACK', 'SHOULDER_ISOLATION', 'FIRST_TIME', 'REPS_SETS', '허리를 곧게 유지하며 상체를 숙이고 양팔을 아래로 자연스럽게 내려주세요.\n양팔을 Y자, T자, W자 모양으로 차례로 들어 올리며 날개뼈를 부드럽게 움직여주세요.\n어깨를 으쓱하거나 반동을 사용하지 말고 천천히 동작해주세요.', 'https://www.youtube.com/watch?v=R6hm0NI_e58') ON DUPLICATE KEY UPDATE name_ko=VALUES(name_ko), name_en=VALUES(name_en), exercise_type=VALUES(exercise_type), primary_muscle=VALUES(primary_muscle), movement_pattern=VALUES(movement_pattern), minimum_experience_level=VALUES(minimum_experience_level), baseline_record_type=VALUES(baseline_record_type), guide=VALUES(guide), video_url=VALUES(video_url);
INSERT INTO exercise (exercise_code, name_ko, name_en, exercise_type, primary_muscle, movement_pattern, minimum_experience_level, baseline_record_type, guide, video_url) VALUES ('EX_BACK_DB_BENT_ROW', '덤벨 벤트오버 로우', 'Dumbbell Bent-over Row', 'STRENGTH', 'BACK', 'HORIZONTAL_PULL', 'BEGINNER', 'WEIGHT_REPS_SETS', '양손에 덤벨을 들고 무릎을 살짝 굽힌 뒤 엉덩이를 뒤로 빼며 상체를 숙여주세요.\n팔꿈치를 몸통 뒤쪽으로 당겨 덤벨을 허리 가까이 올렸다가 천천히 내려주세요.\n등이 둥글게 말리거나 상체가 반동으로 들리지 않도록 주의해주세요.', 'https://www.youtube.com/watch?v=6gvmcqr226U') ON DUPLICATE KEY UPDATE name_ko=VALUES(name_ko), name_en=VALUES(name_en), exercise_type=VALUES(exercise_type), primary_muscle=VALUES(primary_muscle), movement_pattern=VALUES(movement_pattern), minimum_experience_level=VALUES(minimum_experience_level), baseline_record_type=VALUES(baseline_record_type), guide=VALUES(guide), video_url=VALUES(video_url);
INSERT INTO exercise (exercise_code, name_ko, name_en, exercise_type, primary_muscle, movement_pattern, minimum_experience_level, baseline_record_type, guide, video_url) VALUES ('EX_BACK_ONE_ARM_DB_ROW', '원암 덤벨 로우', 'One-arm Dumbbell Row', 'STRENGTH', 'BACK', 'HORIZONTAL_PULL', 'BEGINNER', 'WEIGHT_REPS_SETS', '한쪽 손과 무릎을 벤치에 지지하고 반대쪽 손으로 덤벨을 잡아주세요.\n등을 곧게 유지하며 덤벨을 허리 옆으로 당겼다가 천천히 내려주세요.\n몸통이 옆으로 회전하거나 어깨가 과도하게 올라가지 않도록 주의해주세요.', 'https://www.youtube.com/watch?v=ZRSGpBUVcNw') ON DUPLICATE KEY UPDATE name_ko=VALUES(name_ko), name_en=VALUES(name_en), exercise_type=VALUES(exercise_type), primary_muscle=VALUES(primary_muscle), movement_pattern=VALUES(movement_pattern), minimum_experience_level=VALUES(minimum_experience_level), baseline_record_type=VALUES(baseline_record_type), guide=VALUES(guide), video_url=VALUES(video_url);
INSERT INTO exercise (exercise_code, name_ko, name_en, exercise_type, primary_muscle, movement_pattern, minimum_experience_level, baseline_record_type, guide, video_url) VALUES ('EX_BACK_BAND_SEATED_ROW', '밴드 시티드 로우', 'Band Seated Row', 'STRENGTH', 'BACK', 'HORIZONTAL_PULL', 'FIRST_TIME', 'REPS_SETS', '바닥에 앉아 다리를 앞으로 뻗고 밴드를 양발에 안정적으로 걸어주세요.\n허리를 곧게 편 상태에서 팔꿈치를 뒤로 당겼다가 천천히 펴주세요.\n상체를 앞뒤로 흔들거나 어깨를 으쓱하지 않도록 주의해주세요.', 'https://www.youtube.com/watch?v=ybLaUiJaNxI') ON DUPLICATE KEY UPDATE name_ko=VALUES(name_ko), name_en=VALUES(name_en), exercise_type=VALUES(exercise_type), primary_muscle=VALUES(primary_muscle), movement_pattern=VALUES(movement_pattern), minimum_experience_level=VALUES(minimum_experience_level), baseline_record_type=VALUES(baseline_record_type), guide=VALUES(guide), video_url=VALUES(video_url);
INSERT INTO exercise (exercise_code, name_ko, name_en, exercise_type, primary_muscle, movement_pattern, minimum_experience_level, baseline_record_type, guide, video_url) VALUES ('EX_BACK_LAT_PULLDOWN', '랫풀다운', 'Lat Pulldown', 'STRENGTH', 'BACK', 'VERTICAL_PULL', 'FIRST_TIME', 'WEIGHT_REPS_SETS', '허벅지를 패드에 고정하고 바를 어깨너비보다 약간 넓게 잡아주세요.\n가슴을 편 상태에서 팔꿈치를 아래로 당겨 바를 윗가슴 쪽으로 내려주세요.\n상체를 과도하게 뒤로 젖히거나 바를 목 뒤로 당기지 않도록 주의해주세요.', 'https://www.youtube.com/watch?v=JGeRYIZdojU') ON DUPLICATE KEY UPDATE name_ko=VALUES(name_ko), name_en=VALUES(name_en), exercise_type=VALUES(exercise_type), primary_muscle=VALUES(primary_muscle), movement_pattern=VALUES(movement_pattern), minimum_experience_level=VALUES(minimum_experience_level), baseline_record_type=VALUES(baseline_record_type), guide=VALUES(guide), video_url=VALUES(video_url);
INSERT INTO exercise (exercise_code, name_ko, name_en, exercise_type, primary_muscle, movement_pattern, minimum_experience_level, baseline_record_type, guide, video_url) VALUES ('EX_BACK_SEATED_CABLE_ROW', '시티드 케이블 로우', 'Seated Cable Row', 'STRENGTH', 'BACK', 'HORIZONTAL_PULL', 'FIRST_TIME', 'WEIGHT_REPS_SETS', '발을 발판에 고정하고 무릎을 살짝 굽힌 상태에서 손잡이를 잡아주세요.\n허리를 곧게 편 상태에서 팔꿈치를 뒤로 당겨 손잡이를 배 쪽으로 가져와 주세요.\n상체를 과도하게 젖히거나 반동으로 무게를 당기지 않도록 주의해주세요.', 'https://www.youtube.com/watch?v=lJoozxC0Rns') ON DUPLICATE KEY UPDATE name_ko=VALUES(name_ko), name_en=VALUES(name_en), exercise_type=VALUES(exercise_type), primary_muscle=VALUES(primary_muscle), movement_pattern=VALUES(movement_pattern), minimum_experience_level=VALUES(minimum_experience_level), baseline_record_type=VALUES(baseline_record_type), guide=VALUES(guide), video_url=VALUES(video_url);
INSERT INTO exercise (exercise_code, name_ko, name_en, exercise_type, primary_muscle, movement_pattern, minimum_experience_level, baseline_record_type, guide, video_url) VALUES ('EX_BACK_BB_ROW', '바벨 로우', 'Barbell Row', 'STRENGTH', 'BACK', 'HORIZONTAL_PULL', 'INTERMEDIATE', 'WEIGHT_REPS_SETS', '발을 골반너비로 벌리고 무릎을 살짝 굽힌 뒤 상체를 앞으로 숙여주세요.\n등을 곧게 유지하며 바벨을 배 쪽으로 당겼다가 천천히 내려주세요.\n허리가 둥글게 말리거나 상체를 흔들어 반동을 사용하지 않도록 주의해주세요.', 'https://www.youtube.com/watch?v=FsK19s8eGFs') ON DUPLICATE KEY UPDATE name_ko=VALUES(name_ko), name_en=VALUES(name_en), exercise_type=VALUES(exercise_type), primary_muscle=VALUES(primary_muscle), movement_pattern=VALUES(movement_pattern), minimum_experience_level=VALUES(minimum_experience_level), baseline_record_type=VALUES(baseline_record_type), guide=VALUES(guide), video_url=VALUES(video_url);
INSERT INTO exercise (exercise_code, name_ko, name_en, exercise_type, primary_muscle, movement_pattern, minimum_experience_level, baseline_record_type, guide, video_url) VALUES ('EX_BACK_ASSISTED_PULLUP', '어시스트 풀업 머신', 'Assisted Pull-up Machine', 'STRENGTH', 'BACK', 'VERTICAL_PULL', 'FIRST_TIME', 'REPS_SETS', '무릎을 패드에 올리고 가슴을 편 상태에서 손잡이를 잡아주세요.\n등에 힘을 주며 턱이 손잡이 높이에 가까워질 때까지 몸을 당겨주세요.\n반동을 사용하지 말고 천천히 팔을 펴며 내려오세요.', 'https://www.youtube.com/watch?v=gx0RWT7WbmA') ON DUPLICATE KEY UPDATE name_ko=VALUES(name_ko), name_en=VALUES(name_en), exercise_type=VALUES(exercise_type), primary_muscle=VALUES(primary_muscle), movement_pattern=VALUES(movement_pattern), minimum_experience_level=VALUES(minimum_experience_level), baseline_record_type=VALUES(baseline_record_type), guide=VALUES(guide), video_url=VALUES(video_url);
INSERT INTO exercise (exercise_code, name_ko, name_en, exercise_type, primary_muscle, movement_pattern, minimum_experience_level, baseline_record_type, guide, video_url) VALUES ('EX_BACK_EXTENSION', '백 익스텐션', 'Back Extension', 'STRENGTH', 'BACK', 'HINGE', 'BEGINNER', 'REPS_SETS', '패드에 허벅지를 고정하고 척추를 자연스럽게 유지해주세요.\n엉덩이와 허리에 힘을 주며 상체를 천천히 들어 올려주세요.\n허리가 과도하게 꺾이지 않도록 몸이 일직선이 되는 지점까지만 올라오세요.', 'https://www.youtube.com/watch?v=H8Swl1N-uis') ON DUPLICATE KEY UPDATE name_ko=VALUES(name_ko), name_en=VALUES(name_en), exercise_type=VALUES(exercise_type), primary_muscle=VALUES(primary_muscle), movement_pattern=VALUES(movement_pattern), minimum_experience_level=VALUES(minimum_experience_level), baseline_record_type=VALUES(baseline_record_type), guide=VALUES(guide), video_url=VALUES(video_url);
INSERT INTO exercise (exercise_code, name_ko, name_en, exercise_type, primary_muscle, movement_pattern, minimum_experience_level, baseline_record_type, guide, video_url) VALUES ('EX_SHOULDER_PIKE_PUSHUP', '파이크 푸시업', 'Pike Push-up', 'STRENGTH', 'SHOULDERS', 'VERTICAL_PUSH', 'INTERMEDIATE', 'REPS_SETS', '엉덩이를 높이 들어 몸이 역 V자가 되도록 자세를 잡아주세요.\n팔꿈치를 굽히며 머리가 바닥을 향하도록 상체를 천천히 내려주세요.\n허리가 무너지지 않도록 코어에 힘을 주고 손바닥으로 바닥을 밀어 올라오세요.', 'https://www.youtube.com/watch?v=XckEEwa1BPI') ON DUPLICATE KEY UPDATE name_ko=VALUES(name_ko), name_en=VALUES(name_en), exercise_type=VALUES(exercise_type), primary_muscle=VALUES(primary_muscle), movement_pattern=VALUES(movement_pattern), minimum_experience_level=VALUES(minimum_experience_level), baseline_record_type=VALUES(baseline_record_type), guide=VALUES(guide), video_url=VALUES(video_url);
INSERT INTO exercise (exercise_code, name_ko, name_en, exercise_type, primary_muscle, movement_pattern, minimum_experience_level, baseline_record_type, guide, video_url) VALUES ('EX_SHOULDER_DB_PRESS', '덤벨 숄더 프레스', 'Dumbbell Shoulder Press', 'STRENGTH', 'SHOULDERS', 'VERTICAL_PUSH', 'BEGINNER', 'WEIGHT_REPS_SETS', '덤벨을 어깨 높이에 들고 가슴을 편 상태로 준비해주세요.\n팔꿈치를 펴며 덤벨을 머리 위로 밀어 올려주세요.\n허리가 과도하게 꺾이지 않도록 복부에 힘을 주며 천천히 내려오세요.', 'https://www.youtube.com/watch?v=Did01dFR3Lk') ON DUPLICATE KEY UPDATE name_ko=VALUES(name_ko), name_en=VALUES(name_en), exercise_type=VALUES(exercise_type), primary_muscle=VALUES(primary_muscle), movement_pattern=VALUES(movement_pattern), minimum_experience_level=VALUES(minimum_experience_level), baseline_record_type=VALUES(baseline_record_type), guide=VALUES(guide), video_url=VALUES(video_url);
INSERT INTO exercise (exercise_code, name_ko, name_en, exercise_type, primary_muscle, movement_pattern, minimum_experience_level, baseline_record_type, guide, video_url) VALUES ('EX_SHOULDER_DB_LATERAL_RAISE', '덤벨 사이드 라테럴 레이즈', 'Dumbbell Side Lateral Raise', 'STRENGTH', 'SHOULDERS', 'SHOULDER_ISOLATION', 'FIRST_TIME', 'WEIGHT_REPS_SETS', '덤벨을 양옆에 들고 팔꿈치를 살짝 굽힌 상태로 서주세요.\n어깨에 힘을 주며 양팔을 옆으로 어깨 높이까지 들어 올려주세요.\n반동이나 승모근 사용을 줄이고 천천히 시작 자세로 돌아오세요.', 'https://www.youtube.com/watch?v=3VcKaXpzqRo') ON DUPLICATE KEY UPDATE name_ko=VALUES(name_ko), name_en=VALUES(name_en), exercise_type=VALUES(exercise_type), primary_muscle=VALUES(primary_muscle), movement_pattern=VALUES(movement_pattern), minimum_experience_level=VALUES(minimum_experience_level), baseline_record_type=VALUES(baseline_record_type), guide=VALUES(guide), video_url=VALUES(video_url);
INSERT INTO exercise (exercise_code, name_ko, name_en, exercise_type, primary_muscle, movement_pattern, minimum_experience_level, baseline_record_type, guide, video_url) VALUES ('EX_SHOULDER_DB_FRONT_RAISE', '덤벨 프론트 레이즈', 'Dumbbell Front Raise', 'STRENGTH', 'SHOULDERS', 'SHOULDER_ISOLATION', 'FIRST_TIME', 'WEIGHT_REPS_SETS', '덤벨을 허벅지 앞에 들고 상체를 곧게 세워주세요.\n팔꿈치를 살짝 굽힌 채 덤벨을 정면으로 어깨 높이까지 들어 올려주세요.\n몸의 반동을 사용하지 말고 어깨의 힘으로 천천히 내려주세요.', 'https://www.youtube.com/watch?v=-t7fuZ0KhDA') ON DUPLICATE KEY UPDATE name_ko=VALUES(name_ko), name_en=VALUES(name_en), exercise_type=VALUES(exercise_type), primary_muscle=VALUES(primary_muscle), movement_pattern=VALUES(movement_pattern), minimum_experience_level=VALUES(minimum_experience_level), baseline_record_type=VALUES(baseline_record_type), guide=VALUES(guide), video_url=VALUES(video_url);
INSERT INTO exercise (exercise_code, name_ko, name_en, exercise_type, primary_muscle, movement_pattern, minimum_experience_level, baseline_record_type, guide, video_url) VALUES ('EX_SHOULDER_BAND_LATERAL_RAISE', '밴드 라테럴 레이즈', 'Band Lateral Raise', 'STRENGTH', 'SHOULDERS', 'SHOULDER_ISOLATION', 'FIRST_TIME', 'REPS_SETS', '밴드를 발로 밟고 양손으로 잡은 뒤 상체를 곧게 세워주세요.\n팔꿈치를 살짝 굽힌 상태에서 양팔을 옆으로 어깨 높이까지 들어 올려주세요.\n밴드의 장력을 유지하며 팔을 천천히 내려주세요.', 'https://www.youtube.com/watch?v=yfNg5sFndbw') ON DUPLICATE KEY UPDATE name_ko=VALUES(name_ko), name_en=VALUES(name_en), exercise_type=VALUES(exercise_type), primary_muscle=VALUES(primary_muscle), movement_pattern=VALUES(movement_pattern), minimum_experience_level=VALUES(minimum_experience_level), baseline_record_type=VALUES(baseline_record_type), guide=VALUES(guide), video_url=VALUES(video_url);
INSERT INTO exercise (exercise_code, name_ko, name_en, exercise_type, primary_muscle, movement_pattern, minimum_experience_level, baseline_record_type, guide, video_url) VALUES ('EX_SHOULDER_BB_OHP', '바벨 오버헤드 프레스', 'Barbell Overhead Press (OHP)', 'STRENGTH', 'SHOULDERS', 'VERTICAL_PUSH', 'INTERMEDIATE', 'WEIGHT_REPS_SETS', '바벨을 어깨 앞쪽에 두고 손을 어깨보다 약간 넓게 잡아주세요.\n복부와 엉덩이에 힘을 준 상태에서 바벨을 머리 위로 밀어 올려주세요.\n허리가 과도하게 젖혀지지 않도록 유지하며 천천히 내려오세요.', 'https://www.youtube.com/watch?v=cGnhixvC8uA') ON DUPLICATE KEY UPDATE name_ko=VALUES(name_ko), name_en=VALUES(name_en), exercise_type=VALUES(exercise_type), primary_muscle=VALUES(primary_muscle), movement_pattern=VALUES(movement_pattern), minimum_experience_level=VALUES(minimum_experience_level), baseline_record_type=VALUES(baseline_record_type), guide=VALUES(guide), video_url=VALUES(video_url);
INSERT INTO exercise (exercise_code, name_ko, name_en, exercise_type, primary_muscle, movement_pattern, minimum_experience_level, baseline_record_type, guide, video_url) VALUES ('EX_SHOULDER_PRESS_MACHINE', '숄더 프레스 머신', 'Shoulder Press Machine', 'STRENGTH', 'SHOULDERS', 'VERTICAL_PUSH', 'FIRST_TIME', 'WEIGHT_REPS_SETS', '등과 엉덩이를 등받이에 붙이고 손잡이가 어깨 높이에 오도록 조절해주세요.\n손잡이를 위로 밀어 올리며 팔을 자연스럽게 펴주세요.\n어깨가 들리지 않도록 유지하며 천천히 시작 위치로 돌아오세요.', 'https://www.youtube.com/watch?v=GcY6TZxfS0k') ON DUPLICATE KEY UPDATE name_ko=VALUES(name_ko), name_en=VALUES(name_en), exercise_type=VALUES(exercise_type), primary_muscle=VALUES(primary_muscle), movement_pattern=VALUES(movement_pattern), minimum_experience_level=VALUES(minimum_experience_level), baseline_record_type=VALUES(baseline_record_type), guide=VALUES(guide), video_url=VALUES(video_url);
INSERT INTO exercise (exercise_code, name_ko, name_en, exercise_type, primary_muscle, movement_pattern, minimum_experience_level, baseline_record_type, guide, video_url) VALUES ('EX_SHOULDER_CABLE_LATERAL_RAISE', '케이블 라테럴 레이즈', 'Cable Lateral Raise', 'STRENGTH', 'SHOULDERS', 'SHOULDER_ISOLATION', 'BEGINNER', 'WEIGHT_REPS_SETS', '케이블 손잡이를 잡고 몸을 곧게 세운 상태로 준비해주세요.\n팔꿈치를 살짝 굽힌 채 팔을 옆으로 어깨 높이까지 들어 올려주세요.\n몸을 기울이거나 반동을 사용하지 말고 천천히 내려주세요.', 'https://www.youtube.com/watch?v=Z5FA9aq3L6A') ON DUPLICATE KEY UPDATE name_ko=VALUES(name_ko), name_en=VALUES(name_en), exercise_type=VALUES(exercise_type), primary_muscle=VALUES(primary_muscle), movement_pattern=VALUES(movement_pattern), minimum_experience_level=VALUES(minimum_experience_level), baseline_record_type=VALUES(baseline_record_type), guide=VALUES(guide), video_url=VALUES(video_url);
INSERT INTO exercise (exercise_code, name_ko, name_en, exercise_type, primary_muscle, movement_pattern, minimum_experience_level, baseline_record_type, guide, video_url) VALUES ('EX_SHOULDER_REVERSE_PEC_DECK', '리버스 펙덱 플라이', 'Reverse Pec Deck Fly', 'STRENGTH', 'SHOULDERS', 'HORIZONTAL_PULL', 'FIRST_TIME', 'WEIGHT_REPS_SETS', '가슴을 패드에 붙이고 양손으로 손잡이를 잡아주세요.\n팔꿈치를 살짝 굽힌 상태에서 양팔을 뒤쪽으로 벌려주세요.\n어깨가 올라가지 않도록 유지하며 천천히 시작 자세로 돌아오세요.', 'https://www.youtube.com/watch?v=H7_Lk-tN28o') ON DUPLICATE KEY UPDATE name_ko=VALUES(name_ko), name_en=VALUES(name_en), exercise_type=VALUES(exercise_type), primary_muscle=VALUES(primary_muscle), movement_pattern=VALUES(movement_pattern), minimum_experience_level=VALUES(minimum_experience_level), baseline_record_type=VALUES(baseline_record_type), guide=VALUES(guide), video_url=VALUES(video_url);
INSERT INTO exercise (exercise_code, name_ko, name_en, exercise_type, primary_muscle, movement_pattern, minimum_experience_level, baseline_record_type, guide, video_url) VALUES ('EX_LEGS_AIR_SQUAT', '맨몸 스쿼트', 'Air Squat', 'STRENGTH', 'LEGS_GLUTES', 'SQUAT', 'FIRST_TIME', 'REPS_SETS', '발을 어깨너비 정도로 벌리고 발끝을 자연스럽게 바깥으로 향해주세요.\n엉덩이를 뒤로 보내며 무릎과 고관절을 함께 굽혀 내려가세요.\n무릎이 안쪽으로 모이지 않도록 유지하며 발바닥으로 바닥을 밀어 일어나세요.', 'https://www.youtube.com/watch?v=l83R5PblSMA') ON DUPLICATE KEY UPDATE name_ko=VALUES(name_ko), name_en=VALUES(name_en), exercise_type=VALUES(exercise_type), primary_muscle=VALUES(primary_muscle), movement_pattern=VALUES(movement_pattern), minimum_experience_level=VALUES(minimum_experience_level), baseline_record_type=VALUES(baseline_record_type), guide=VALUES(guide), video_url=VALUES(video_url);
INSERT INTO exercise (exercise_code, name_ko, name_en, exercise_type, primary_muscle, movement_pattern, minimum_experience_level, baseline_record_type, guide, video_url) VALUES ('EX_LEGS_FORWARD_LUNGE', '포워드 런지', 'Forward Lunge', 'STRENGTH', 'LEGS_GLUTES', 'LUNGE', 'BEGINNER', 'REPS_SETS', '상체를 곧게 세우고 한쪽 발을 앞으로 크게 내디뎌주세요.\n양쪽 무릎을 굽혀 뒤쪽 무릎이 바닥 가까이 내려가도록 앉아주세요.\n앞쪽 무릎이 안쪽으로 무너지지 않도록 유지하며 앞발로 바닥을 밀어 돌아오세요.', 'https://www.youtube.com/watch?v=xrPteyQLGAo') ON DUPLICATE KEY UPDATE name_ko=VALUES(name_ko), name_en=VALUES(name_en), exercise_type=VALUES(exercise_type), primary_muscle=VALUES(primary_muscle), movement_pattern=VALUES(movement_pattern), minimum_experience_level=VALUES(minimum_experience_level), baseline_record_type=VALUES(baseline_record_type), guide=VALUES(guide), video_url=VALUES(video_url);
INSERT INTO exercise (exercise_code, name_ko, name_en, exercise_type, primary_muscle, movement_pattern, minimum_experience_level, baseline_record_type, guide, video_url) VALUES ('EX_LEGS_REVERSE_LUNGE', '리버스 런지', 'Reverse Lunge', 'STRENGTH', 'LEGS_GLUTES', 'LUNGE', 'BEGINNER', 'REPS_SETS', '상체를 곧게 세운 상태에서 한쪽 발을 뒤로 크게 내디뎌주세요.\n양쪽 무릎을 굽혀 뒤쪽 무릎이 바닥 가까이 내려가도록 앉아주세요.\n앞발에 체중을 유지하며 바닥을 밀어 시작 자세로 돌아오세요.', 'https://www.youtube.com/watch?v=Q2k3kYbtOcI') ON DUPLICATE KEY UPDATE name_ko=VALUES(name_ko), name_en=VALUES(name_en), exercise_type=VALUES(exercise_type), primary_muscle=VALUES(primary_muscle), movement_pattern=VALUES(movement_pattern), minimum_experience_level=VALUES(minimum_experience_level), baseline_record_type=VALUES(baseline_record_type), guide=VALUES(guide), video_url=VALUES(video_url);
INSERT INTO exercise (exercise_code, name_ko, name_en, exercise_type, primary_muscle, movement_pattern, minimum_experience_level, baseline_record_type, guide, video_url) VALUES ('EX_LEGS_SIDE_LUNGE', '사이드 런지', 'Side Lunge', 'STRENGTH', 'LEGS_GLUTES', 'LUNGE', 'BEGINNER', 'REPS_SETS', '발을 모으고 선 상태에서 한쪽 발을 옆으로 넓게 내디뎌주세요.\n이동한 쪽 엉덩이를 뒤로 보내며 무릎을 굽히고 반대쪽 다리는 펴주세요.\n굽힌 무릎이 안쪽으로 무너지지 않도록 유지하며 시작 자세로 돌아오세요.', 'https://www.youtube.com/watch?v=URQvRQT0XMA') ON DUPLICATE KEY UPDATE name_ko=VALUES(name_ko), name_en=VALUES(name_en), exercise_type=VALUES(exercise_type), primary_muscle=VALUES(primary_muscle), movement_pattern=VALUES(movement_pattern), minimum_experience_level=VALUES(minimum_experience_level), baseline_record_type=VALUES(baseline_record_type), guide=VALUES(guide), video_url=VALUES(video_url);
INSERT INTO exercise (exercise_code, name_ko, name_en, exercise_type, primary_muscle, movement_pattern, minimum_experience_level, baseline_record_type, guide, video_url) VALUES ('EX_LEGS_BULGARIAN_SPLIT_SQUAT', '불가리안 스플릿 스쿼트', 'Bulgarian Split Squat', 'STRENGTH', 'LEGS_GLUTES', 'LUNGE', 'INTERMEDIATE', 'REPS_SETS', '한쪽 발등을 뒤쪽 벤치에 올리고 앞발을 충분히 앞으로 놓아주세요.\n상체를 안정적으로 유지하며 앞쪽 무릎을 굽혀 몸을 아래로 내려주세요.\n앞쪽 무릎이 안쪽으로 무너지지 않도록 유지하며 앞발로 바닥을 밀어 올라오세요.', 'https://www.youtube.com/watch?v=vq5-vdgJc0I&t=73s') ON DUPLICATE KEY UPDATE name_ko=VALUES(name_ko), name_en=VALUES(name_en), exercise_type=VALUES(exercise_type), primary_muscle=VALUES(primary_muscle), movement_pattern=VALUES(movement_pattern), minimum_experience_level=VALUES(minimum_experience_level), baseline_record_type=VALUES(baseline_record_type), guide=VALUES(guide), video_url=VALUES(video_url);
INSERT INTO exercise (exercise_code, name_ko, name_en, exercise_type, primary_muscle, movement_pattern, minimum_experience_level, baseline_record_type, guide, video_url) VALUES ('EX_LEGS_PISTOL_SQUAT', '피스톨 스쿼트', 'Pistol Squat', 'STRENGTH', 'LEGS_GLUTES', 'SQUAT', 'ADVANCED', 'REPS_SETS', '한쪽 다리를 앞으로 뻗고 반대쪽 발로 균형을 잡아주세요.\n지지하는 다리의 무릎과 고관절을 굽히며 천천히 몸을 내려주세요.\n무릎이 안쪽으로 무너지지 않도록 유지하며 발 전체로 바닥을 밀어 올라오세요.', 'https://www.youtube.com/watch?v=ZI3gB5irv5g') ON DUPLICATE KEY UPDATE name_ko=VALUES(name_ko), name_en=VALUES(name_en), exercise_type=VALUES(exercise_type), primary_muscle=VALUES(primary_muscle), movement_pattern=VALUES(movement_pattern), minimum_experience_level=VALUES(minimum_experience_level), baseline_record_type=VALUES(baseline_record_type), guide=VALUES(guide), video_url=VALUES(video_url);
INSERT INTO exercise (exercise_code, name_ko, name_en, exercise_type, primary_muscle, movement_pattern, minimum_experience_level, baseline_record_type, guide, video_url) VALUES ('EX_LEGS_GLUTE_BRIDGE', '글루트 브릿지', 'Glute Bridge', 'STRENGTH', 'LEGS_GLUTES', 'HIP_EXTENSION', 'FIRST_TIME', 'REPS_SETS', '등을 바닥에 대고 누운 뒤 무릎을 굽혀 발바닥을 바닥에 붙여주세요.\n엉덩이에 힘을 주며 어깨부터 무릎까지 일직선이 되도록 골반을 들어 올려주세요.\n허리를 과도하게 꺾지 말고 엉덩이의 긴장을 유지하며 천천히 내려오세요.', 'https://www.youtube.com/watch?v=L9KZfxT654Y') ON DUPLICATE KEY UPDATE name_ko=VALUES(name_ko), name_en=VALUES(name_en), exercise_type=VALUES(exercise_type), primary_muscle=VALUES(primary_muscle), movement_pattern=VALUES(movement_pattern), minimum_experience_level=VALUES(minimum_experience_level), baseline_record_type=VALUES(baseline_record_type), guide=VALUES(guide), video_url=VALUES(video_url);
INSERT INTO exercise (exercise_code, name_ko, name_en, exercise_type, primary_muscle, movement_pattern, minimum_experience_level, baseline_record_type, guide, video_url) VALUES ('EX_LEGS_STANDING_CALF_RAISE', '스탠딩 카프 레이즈', 'Standing Calf Raise', 'STRENGTH', 'LEGS_GLUTES', 'KNEE_ISOLATION', 'FIRST_TIME', 'REPS_SETS', '발을 골반 너비로 벌리고 상체를 곧게 세워주세요.\n발뒤꿈치를 최대한 높이 들어 종아리를 수축해주세요.\n발목이 바깥이나 안쪽으로 꺾이지 않도록 유지하며 천천히 내려오세요.', 'https://www.youtube.com/watch?v=eMTy3qylqnE') ON DUPLICATE KEY UPDATE name_ko=VALUES(name_ko), name_en=VALUES(name_en), exercise_type=VALUES(exercise_type), primary_muscle=VALUES(primary_muscle), movement_pattern=VALUES(movement_pattern), minimum_experience_level=VALUES(minimum_experience_level), baseline_record_type=VALUES(baseline_record_type), guide=VALUES(guide), video_url=VALUES(video_url);
INSERT INTO exercise (exercise_code, name_ko, name_en, exercise_type, primary_muscle, movement_pattern, minimum_experience_level, baseline_record_type, guide, video_url) VALUES ('EX_LEGS_DB_GOBLET_SQUAT', '덤벨 고블렛 스쿼트', 'Dumbbell Goblet Squat', 'STRENGTH', 'LEGS_GLUTES', 'SQUAT', 'BEGINNER', 'WEIGHT_REPS_SETS', '덤벨 하나를 가슴 앞에 들고 발을 어깨너비 정도로 벌려주세요.\n가슴을 편 상태에서 엉덩이를 뒤로 보내며 천천히 앉아주세요.\n무릎이 안쪽으로 모이지 않도록 유지하며 발바닥으로 바닥을 밀어 일어나세요.', 'https://www.youtube.com/watch?v=MeIiIdhvXT4') ON DUPLICATE KEY UPDATE name_ko=VALUES(name_ko), name_en=VALUES(name_en), exercise_type=VALUES(exercise_type), primary_muscle=VALUES(primary_muscle), movement_pattern=VALUES(movement_pattern), minimum_experience_level=VALUES(minimum_experience_level), baseline_record_type=VALUES(baseline_record_type), guide=VALUES(guide), video_url=VALUES(video_url);
INSERT INTO exercise (exercise_code, name_ko, name_en, exercise_type, primary_muscle, movement_pattern, minimum_experience_level, baseline_record_type, guide, video_url) VALUES ('EX_LEGS_DB_LUNGE', '덤벨 런지', 'Dumbbell Lunge', 'STRENGTH', 'LEGS_GLUTES', 'LUNGE', 'BEGINNER', 'WEIGHT_REPS_SETS', '양손에 덤벨을 들고 상체를 곧게 세운 상태로 준비해주세요.\n한쪽 발을 앞으로 내디딘 뒤 양쪽 무릎을 굽혀 몸을 내려주세요.\n앞쪽 무릎이 안쪽으로 무너지지 않도록 유지하며 앞발로 바닥을 밀어 돌아오세요.', 'https://www.youtube.com/watch?v=lf4gJgKyLpI') ON DUPLICATE KEY UPDATE name_ko=VALUES(name_ko), name_en=VALUES(name_en), exercise_type=VALUES(exercise_type), primary_muscle=VALUES(primary_muscle), movement_pattern=VALUES(movement_pattern), minimum_experience_level=VALUES(minimum_experience_level), baseline_record_type=VALUES(baseline_record_type), guide=VALUES(guide), video_url=VALUES(video_url);
INSERT INTO exercise (exercise_code, name_ko, name_en, exercise_type, primary_muscle, movement_pattern, minimum_experience_level, baseline_record_type, guide, video_url) VALUES ('EX_LEGS_DB_RDL', '덤벨 루마니안 데드리프트', 'Dumbbell Romanian Deadlift', 'STRENGTH', 'LEGS_GLUTES', 'HINGE', 'BEGINNER', 'WEIGHT_REPS_SETS', '덤벨을 허벅지 앞에 들고 무릎을 살짝 굽힌 상태로 서주세요.\n허리를 곧게 유지하며 엉덩이를 뒤로 보내 덤벨을 다리를 따라 내려주세요.\n햄스트링이 충분히 늘어나면 엉덩이를 앞으로 밀며 시작 자세로 돌아오세요.', 'https://www.youtube.com/watch?v=5WxMW-Fu5KU') ON DUPLICATE KEY UPDATE name_ko=VALUES(name_ko), name_en=VALUES(name_en), exercise_type=VALUES(exercise_type), primary_muscle=VALUES(primary_muscle), movement_pattern=VALUES(movement_pattern), minimum_experience_level=VALUES(minimum_experience_level), baseline_record_type=VALUES(baseline_record_type), guide=VALUES(guide), video_url=VALUES(video_url);
INSERT INTO exercise (exercise_code, name_ko, name_en, exercise_type, primary_muscle, movement_pattern, minimum_experience_level, baseline_record_type, guide, video_url) VALUES ('EX_LEGS_KB_SWING', '케틀벨 스윙', 'Kettlebell Swing', 'STRENGTH', 'LEGS_GLUTES', 'HINGE', 'INTERMEDIATE', 'WEIGHT_REPS_SETS', '양손으로 케틀벨을 잡고 발을 어깨너비보다 약간 넓게 벌려주세요.\n엉덩이를 뒤로 보냈다가 강하게 펴는 힘으로 케틀벨을 앞쪽으로 스윙해주세요.\n팔로 들어 올리기보다 엉덩이의 힘을 사용하고 허리가 과도하게 꺾이지 않도록 해주세요.', 'https://www.youtube.com/watch?v=YSxHifyI6s8') ON DUPLICATE KEY UPDATE name_ko=VALUES(name_ko), name_en=VALUES(name_en), exercise_type=VALUES(exercise_type), primary_muscle=VALUES(primary_muscle), movement_pattern=VALUES(movement_pattern), minimum_experience_level=VALUES(minimum_experience_level), baseline_record_type=VALUES(baseline_record_type), guide=VALUES(guide), video_url=VALUES(video_url);
INSERT INTO exercise (exercise_code, name_ko, name_en, exercise_type, primary_muscle, movement_pattern, minimum_experience_level, baseline_record_type, guide, video_url) VALUES ('EX_LEGS_MINIBAND_CLAMSHELL', '미니밴드 클램쉘', 'Mini-band Clamshell', 'STRENGTH', 'LEGS_GLUTES', 'HIP_ISOLATION', 'FIRST_TIME', 'REPS_SETS', '미니밴드를 무릎 위에 착용하고 옆으로 누워 무릎을 살짝 굽혀주세요.\n발을 붙인 상태에서 위쪽 무릎을 천천히 벌려 엉덩이 옆쪽을 수축해주세요.\n골반이 뒤로 돌아가지 않도록 고정한 채 천천히 무릎을 내려주세요.', 'https://www.youtube.com/watch?v=39vuP5xozsI') ON DUPLICATE KEY UPDATE name_ko=VALUES(name_ko), name_en=VALUES(name_en), exercise_type=VALUES(exercise_type), primary_muscle=VALUES(primary_muscle), movement_pattern=VALUES(movement_pattern), minimum_experience_level=VALUES(minimum_experience_level), baseline_record_type=VALUES(baseline_record_type), guide=VALUES(guide), video_url=VALUES(video_url);
INSERT INTO exercise (exercise_code, name_ko, name_en, exercise_type, primary_muscle, movement_pattern, minimum_experience_level, baseline_record_type, guide, video_url) VALUES ('EX_LEGS_BB_BACK_SQUAT', '바벨 백 스쿼트', 'Barbell Back Squat', 'STRENGTH', 'LEGS_GLUTES', 'SQUAT', 'INTERMEDIATE', 'WEIGHT_REPS_SETS', '바벨을 등 위쪽에 안정적으로 올리고 발을 어깨너비로 벌려주세요.\n가슴을 편 채 엉덩이와 무릎을 함께 굽혀 내려갔다가 발바닥으로 바닥을 밀며 일어나세요.\n허리가 과하게 굽거나 무릎이 안쪽으로 모이지 않도록 주의하세요.', 'https://www.youtube.com/watch?v=3_hRhEgQ_P8') ON DUPLICATE KEY UPDATE name_ko=VALUES(name_ko), name_en=VALUES(name_en), exercise_type=VALUES(exercise_type), primary_muscle=VALUES(primary_muscle), movement_pattern=VALUES(movement_pattern), minimum_experience_level=VALUES(minimum_experience_level), baseline_record_type=VALUES(baseline_record_type), guide=VALUES(guide), video_url=VALUES(video_url);
INSERT INTO exercise (exercise_code, name_ko, name_en, exercise_type, primary_muscle, movement_pattern, minimum_experience_level, baseline_record_type, guide, video_url) VALUES ('EX_LEGS_BB_FRONT_SQUAT', '바벨 프론트 스쿼트', 'Barbell Front Squat', 'STRENGTH', 'LEGS_GLUTES', 'SQUAT', 'INTERMEDIATE', 'WEIGHT_REPS_SETS', '바벨을 어깨 앞쪽에 올리고 팔꿈치를 높게 유지해주세요.\n상체를 세운 채 엉덩이와 무릎을 굽혀 내려갔다가 발바닥으로 바닥을 밀며 일어나세요.\n내려가는 동안 팔꿈치가 떨어지거나 허리가 굽지 않도록 주의하세요.', 'https://www.youtube.com/watch?v=3sX-Smo6sT4') ON DUPLICATE KEY UPDATE name_ko=VALUES(name_ko), name_en=VALUES(name_en), exercise_type=VALUES(exercise_type), primary_muscle=VALUES(primary_muscle), movement_pattern=VALUES(movement_pattern), minimum_experience_level=VALUES(minimum_experience_level), baseline_record_type=VALUES(baseline_record_type), guide=VALUES(guide), video_url=VALUES(video_url);
INSERT INTO exercise (exercise_code, name_ko, name_en, exercise_type, primary_muscle, movement_pattern, minimum_experience_level, baseline_record_type, guide, video_url) VALUES ('EX_LEGS_LEG_PRESS', '레그 프레스', 'Leg Press', 'STRENGTH', 'LEGS_GLUTES', 'SQUAT', 'FIRST_TIME', 'WEIGHT_REPS_SETS', '등과 엉덩이를 등받이에 붙이고 발을 발판에 어깨너비로 놓아주세요.\n무릎을 굽혀 발판을 천천히 내렸다가 발바닥 전체로 밀어 올리세요.\n엉덩이가 들리거나 무릎이 안쪽으로 모이지 않도록 주의하세요.', 'https://www.youtube.com/watch?v=EV0F_3S7Sks') ON DUPLICATE KEY UPDATE name_ko=VALUES(name_ko), name_en=VALUES(name_en), exercise_type=VALUES(exercise_type), primary_muscle=VALUES(primary_muscle), movement_pattern=VALUES(movement_pattern), minimum_experience_level=VALUES(minimum_experience_level), baseline_record_type=VALUES(baseline_record_type), guide=VALUES(guide), video_url=VALUES(video_url);
INSERT INTO exercise (exercise_code, name_ko, name_en, exercise_type, primary_muscle, movement_pattern, minimum_experience_level, baseline_record_type, guide, video_url) VALUES ('EX_LEGS_LEG_EXTENSION', '레그 익스텐션', 'Leg Extension', 'STRENGTH', 'LEGS_GLUTES', 'KNEE_ISOLATION', 'FIRST_TIME', 'WEIGHT_REPS_SETS', '무릎이 기계의 회전축과 나란하도록 앉고 발목을 패드 아래에 놓아주세요.\n허벅지를 고정한 채 무릎을 펴서 패드를 올린 뒤 천천히 내려주세요.\n반동을 쓰거나 무릎을 갑자기 끝까지 밀어 펴지 않도록 주의하세요.', 'https://www.youtube.com/watch?v=mS9iwXhycJI') ON DUPLICATE KEY UPDATE name_ko=VALUES(name_ko), name_en=VALUES(name_en), exercise_type=VALUES(exercise_type), primary_muscle=VALUES(primary_muscle), movement_pattern=VALUES(movement_pattern), minimum_experience_level=VALUES(minimum_experience_level), baseline_record_type=VALUES(baseline_record_type), guide=VALUES(guide), video_url=VALUES(video_url);
INSERT INTO exercise (exercise_code, name_ko, name_en, exercise_type, primary_muscle, movement_pattern, minimum_experience_level, baseline_record_type, guide, video_url) VALUES ('EX_LEGS_LYING_LEG_CURL', '라잉 레그 컬', 'Lying Leg Curl', 'STRENGTH', 'LEGS_GLUTES', 'KNEE_ISOLATION', 'FIRST_TIME', 'WEIGHT_REPS_SETS', '기계에 엎드려 무릎을 회전축에 맞추고 발목 뒤쪽을 패드에 대주세요.\n엉덩이를 패드에 붙인 채 무릎을 굽혀 패드를 당겼다가 천천히 내려주세요.\n허리를 꺾거나 엉덩이가 들리지 않도록 주의하세요.', 'https://www.youtube.com/watch?v=VQefaBdz73w') ON DUPLICATE KEY UPDATE name_ko=VALUES(name_ko), name_en=VALUES(name_en), exercise_type=VALUES(exercise_type), primary_muscle=VALUES(primary_muscle), movement_pattern=VALUES(movement_pattern), minimum_experience_level=VALUES(minimum_experience_level), baseline_record_type=VALUES(baseline_record_type), guide=VALUES(guide), video_url=VALUES(video_url);
INSERT INTO exercise (exercise_code, name_ko, name_en, exercise_type, primary_muscle, movement_pattern, minimum_experience_level, baseline_record_type, guide, video_url) VALUES ('EX_LEGS_BB_HIP_THRUST', '바벨 힙 쓰러스트', 'Barbell Hip Thrust', 'STRENGTH', 'LEGS_GLUTES', 'HIP_EXTENSION', 'INTERMEDIATE', 'WEIGHT_REPS_SETS', '등 위쪽을 벤치에 기대고 바벨을 골반 위에 안정적으로 놓아주세요.\n발바닥으로 바닥을 밀며 엉덩이를 들어 올린 뒤 천천히 내려주세요.\n정점에서 허리를 과하게 젖히지 않도록 주의하세요.', 'https://www.youtube.com/watch?v=OclBmyd-5h0') ON DUPLICATE KEY UPDATE name_ko=VALUES(name_ko), name_en=VALUES(name_en), exercise_type=VALUES(exercise_type), primary_muscle=VALUES(primary_muscle), movement_pattern=VALUES(movement_pattern), minimum_experience_level=VALUES(minimum_experience_level), baseline_record_type=VALUES(baseline_record_type), guide=VALUES(guide), video_url=VALUES(video_url);
INSERT INTO exercise (exercise_code, name_ko, name_en, exercise_type, primary_muscle, movement_pattern, minimum_experience_level, baseline_record_type, guide, video_url) VALUES ('EX_LEGS_ADDUCTOR_MACHINE', '힙 어덕션 머신', 'Hip Adductor Machine', 'STRENGTH', 'LEGS_GLUTES', 'HIP_ISOLATION', 'FIRST_TIME', 'WEIGHT_REPS_SETS', '등받이에 등을 붙이고 허벅지 안쪽이 패드에 닿도록 앉아주세요.\n허벅지 안쪽에 힘을 주어 다리를 모은 뒤 천천히 벌려주세요.\n반동을 쓰거나 무리하게 다리를 벌리지 않도록 주의하세요.', 'https://www.youtube.com/watch?v=JbKtKZwlGVA') ON DUPLICATE KEY UPDATE name_ko=VALUES(name_ko), name_en=VALUES(name_en), exercise_type=VALUES(exercise_type), primary_muscle=VALUES(primary_muscle), movement_pattern=VALUES(movement_pattern), minimum_experience_level=VALUES(minimum_experience_level), baseline_record_type=VALUES(baseline_record_type), guide=VALUES(guide), video_url=VALUES(video_url);
INSERT INTO exercise (exercise_code, name_ko, name_en, exercise_type, primary_muscle, movement_pattern, minimum_experience_level, baseline_record_type, guide, video_url) VALUES ('EX_LEGS_ABDUCTOR_MACHINE', '힙 어브덕션 머신', 'Hip Abductor Machine', 'STRENGTH', 'LEGS_GLUTES', 'HIP_ISOLATION', 'FIRST_TIME', 'WEIGHT_REPS_SETS', '등받이에 등을 붙이고 허벅지 바깥쪽이 패드에 닿도록 앉아주세요.\n엉덩이 옆쪽에 힘을 주어 다리를 벌린 뒤 천천히 모아주세요.\n상체를 흔들거나 반동으로 패드를 밀지 않도록 주의하세요.', 'https://www.youtube.com/watch?v=D_HUq5odZhg') ON DUPLICATE KEY UPDATE name_ko=VALUES(name_ko), name_en=VALUES(name_en), exercise_type=VALUES(exercise_type), primary_muscle=VALUES(primary_muscle), movement_pattern=VALUES(movement_pattern), minimum_experience_level=VALUES(minimum_experience_level), baseline_record_type=VALUES(baseline_record_type), guide=VALUES(guide), video_url=VALUES(video_url);
INSERT INTO exercise (exercise_code, name_ko, name_en, exercise_type, primary_muscle, movement_pattern, minimum_experience_level, baseline_record_type, guide, video_url) VALUES ('EX_TRICEPS_BODYWEIGHT_EXTENSION', '맨몸 삼두 익스텐션', 'Bodyweight Triceps Extension', 'STRENGTH', 'TRICEPS', 'ELBOW_EXTENSION', 'BEGINNER', 'REPS_SETS', '손을 어깨너비로 지지대에 짚고 몸을 곧게 펴주세요.\n팔꿈치를 굽혀 머리를 지지대 쪽으로 낮췄다가 팔꿈치를 펴며 밀어내세요.\n허리가 꺾이거나 팔꿈치가 지나치게 벌어지지 않도록 주의하세요.', 'https://www.youtube.com/watch?v=kzqJ9rhBO4s') ON DUPLICATE KEY UPDATE name_ko=VALUES(name_ko), name_en=VALUES(name_en), exercise_type=VALUES(exercise_type), primary_muscle=VALUES(primary_muscle), movement_pattern=VALUES(movement_pattern), minimum_experience_level=VALUES(minimum_experience_level), baseline_record_type=VALUES(baseline_record_type), guide=VALUES(guide), video_url=VALUES(video_url);
INSERT INTO exercise (exercise_code, name_ko, name_en, exercise_type, primary_muscle, movement_pattern, minimum_experience_level, baseline_record_type, guide, video_url) VALUES ('EX_BICEPS_DB_CURL', '덤벨 바이셉스 컬', 'Dumbbell Biceps Curl', 'STRENGTH', 'BICEPS', 'ELBOW_FLEXION', 'FIRST_TIME', 'WEIGHT_REPS_SETS', '양손에 덤벨을 들고 팔꿈치를 몸통 가까이에 두세요.\n상완을 고정한 채 팔꿈치를 굽혀 덤벨을 올린 뒤 천천히 내려주세요.\n몸을 흔들거나 어깨를 들어 올리지 않도록 주의하세요.', 'https://www.youtube.com/watch?v=cOver4_h5Uw') ON DUPLICATE KEY UPDATE name_ko=VALUES(name_ko), name_en=VALUES(name_en), exercise_type=VALUES(exercise_type), primary_muscle=VALUES(primary_muscle), movement_pattern=VALUES(movement_pattern), minimum_experience_level=VALUES(minimum_experience_level), baseline_record_type=VALUES(baseline_record_type), guide=VALUES(guide), video_url=VALUES(video_url);
INSERT INTO exercise (exercise_code, name_ko, name_en, exercise_type, primary_muscle, movement_pattern, minimum_experience_level, baseline_record_type, guide, video_url) VALUES ('EX_BICEPS_DB_HAMMER_CURL', '덤벨 해머 컬', 'Dumbbell Hammer Curl', 'STRENGTH', 'BICEPS', 'ELBOW_FLEXION', 'FIRST_TIME', 'WEIGHT_REPS_SETS', '손바닥이 서로 마주 보도록 덤벨을 들고 팔꿈치를 몸통 가까이에 두세요.\n손목 방향을 유지한 채 덤벨을 올린 뒤 천천히 내려주세요.\n상체 반동을 쓰거나 손목을 꺾지 않도록 주의하세요.', 'https://www.youtube.com/watch?v=qEUTazhb6EY') ON DUPLICATE KEY UPDATE name_ko=VALUES(name_ko), name_en=VALUES(name_en), exercise_type=VALUES(exercise_type), primary_muscle=VALUES(primary_muscle), movement_pattern=VALUES(movement_pattern), minimum_experience_level=VALUES(minimum_experience_level), baseline_record_type=VALUES(baseline_record_type), guide=VALUES(guide), video_url=VALUES(video_url);
INSERT INTO exercise (exercise_code, name_ko, name_en, exercise_type, primary_muscle, movement_pattern, minimum_experience_level, baseline_record_type, guide, video_url) VALUES ('EX_TRICEPS_DB_OVERHEAD_EXTENSION', '덤벨 오버헤드 트라이셉스 익스텐션', 'Dumbbell Overhead Triceps Extension', 'STRENGTH', 'TRICEPS', 'ELBOW_EXTENSION', 'BEGINNER', 'WEIGHT_REPS_SETS', '덤벨을 머리 위로 들고 팔꿈치가 앞쪽을 향하도록 두세요.\n상완을 고정한 채 팔꿈치를 굽혀 덤벨을 머리 뒤로 내렸다가 다시 펴주세요.\n허리를 과하게 꺾거나 팔꿈치가 크게 벌어지지 않도록 주의하세요.', 'https://www.youtube.com/watch?v=3Nqt05cRhpU') ON DUPLICATE KEY UPDATE name_ko=VALUES(name_ko), name_en=VALUES(name_en), exercise_type=VALUES(exercise_type), primary_muscle=VALUES(primary_muscle), movement_pattern=VALUES(movement_pattern), minimum_experience_level=VALUES(minimum_experience_level), baseline_record_type=VALUES(baseline_record_type), guide=VALUES(guide), video_url=VALUES(video_url);
INSERT INTO exercise (exercise_code, name_ko, name_en, exercise_type, primary_muscle, movement_pattern, minimum_experience_level, baseline_record_type, guide, video_url) VALUES ('EX_BICEPS_BAND_CURL', '밴드 바이셉스 컬', 'Band Biceps Curl', 'STRENGTH', 'BICEPS', 'ELBOW_FLEXION', 'FIRST_TIME', 'REPS_SETS', '밴드 가운데를 발로 밟고 양쪽 끝을 잡아 팔꿈치를 몸통 가까이에 두세요.\n팔꿈치를 굽혀 밴드를 당겼다가 저항을 유지하며 천천히 내려주세요.\n밴드가 발에서 빠지지 않도록 고정하고 몸을 흔들지 마세요.', 'https://www.youtube.com/watch?v=DOZj905WTow') ON DUPLICATE KEY UPDATE name_ko=VALUES(name_ko), name_en=VALUES(name_en), exercise_type=VALUES(exercise_type), primary_muscle=VALUES(primary_muscle), movement_pattern=VALUES(movement_pattern), minimum_experience_level=VALUES(minimum_experience_level), baseline_record_type=VALUES(baseline_record_type), guide=VALUES(guide), video_url=VALUES(video_url);
INSERT INTO exercise (exercise_code, name_ko, name_en, exercise_type, primary_muscle, movement_pattern, minimum_experience_level, baseline_record_type, guide, video_url) VALUES ('EX_BICEPS_BB_CURL', '바벨 컬', 'Barbell Curl', 'STRENGTH', 'BICEPS', 'ELBOW_FLEXION', 'BEGINNER', 'WEIGHT_REPS_SETS', '바벨을 손바닥이 앞을 향하도록 잡고 팔꿈치를 몸통 가까이에 두세요.\n상완을 고정한 채 바벨을 가슴 쪽으로 올렸다가 천천히 내려주세요.\n상체를 뒤로 젖히거나 반동으로 바벨을 올리지 않도록 주의하세요.', 'https://www.youtube.com/watch?v=JN7FmZu3vPo') ON DUPLICATE KEY UPDATE name_ko=VALUES(name_ko), name_en=VALUES(name_en), exercise_type=VALUES(exercise_type), primary_muscle=VALUES(primary_muscle), movement_pattern=VALUES(movement_pattern), minimum_experience_level=VALUES(minimum_experience_level), baseline_record_type=VALUES(baseline_record_type), guide=VALUES(guide), video_url=VALUES(video_url);
INSERT INTO exercise (exercise_code, name_ko, name_en, exercise_type, primary_muscle, movement_pattern, minimum_experience_level, baseline_record_type, guide, video_url) VALUES ('EX_BICEPS_EZ_CURL', 'EZ-바 컬', 'EZ-Bar Curl', 'STRENGTH', 'BICEPS', 'ELBOW_FLEXION', 'BEGINNER', 'WEIGHT_REPS_SETS', 'EZ-바의 굽은 부분을 편한 너비로 잡고 팔꿈치를 몸통 가까이에 두세요.\n상완을 고정한 채 바를 올렸다가 천천히 내려주세요.\n손목을 꺾거나 상체를 흔들어 반동을 쓰지 않도록 주의하세요.', 'https://www.youtube.com/watch?v=GoDF-ck5OZw') ON DUPLICATE KEY UPDATE name_ko=VALUES(name_ko), name_en=VALUES(name_en), exercise_type=VALUES(exercise_type), primary_muscle=VALUES(primary_muscle), movement_pattern=VALUES(movement_pattern), minimum_experience_level=VALUES(minimum_experience_level), baseline_record_type=VALUES(baseline_record_type), guide=VALUES(guide), video_url=VALUES(video_url);
INSERT INTO exercise (exercise_code, name_ko, name_en, exercise_type, primary_muscle, movement_pattern, minimum_experience_level, baseline_record_type, guide, video_url) VALUES ('EX_TRICEPS_CABLE_PUSHDOWN', '케이블 트라이셉스 푸시다운', 'Cable Triceps Pushdown', 'STRENGTH', 'TRICEPS', 'ELBOW_EXTENSION', 'FIRST_TIME', 'WEIGHT_REPS_SETS', '케이블 손잡이를 잡고 팔꿈치를 몸통 가까이에 고정해주세요.\n팔꿈치를 펴며 손잡이를 아래로 누른 뒤 천천히 시작 자세로 돌아오세요.\n어깨를 들거나 상체 반동으로 손잡이를 누르지 않도록 주의하세요.', 'https://www.youtube.com/watch?v=KHPLCjyWM1w') ON DUPLICATE KEY UPDATE name_ko=VALUES(name_ko), name_en=VALUES(name_en), exercise_type=VALUES(exercise_type), primary_muscle=VALUES(primary_muscle), movement_pattern=VALUES(movement_pattern), minimum_experience_level=VALUES(minimum_experience_level), baseline_record_type=VALUES(baseline_record_type), guide=VALUES(guide), video_url=VALUES(video_url);
INSERT INTO exercise (exercise_code, name_ko, name_en, exercise_type, primary_muscle, movement_pattern, minimum_experience_level, baseline_record_type, guide, video_url) VALUES ('EX_BICEPS_CABLE_ROPE_HAMMER_CURL', '케이블 로프 해머 컬', 'Cable Rope Hammer Curl', 'STRENGTH', 'BICEPS', 'ELBOW_FLEXION', 'FIRST_TIME', 'WEIGHT_REPS_SETS', '낮은 케이블에 로프를 연결하고 손바닥이 서로 마주보게 잡아주세요.\n팔꿈치를 몸통 가까이에 둔 채 로프를 어깨 쪽으로 당겼다가 천천히 내려주세요.\n몸을 뒤로 젖히거나 팔꿈치가 앞뒤로 크게 움직이지 않도록 주의하세요.', 'https://www.youtube.com/watch?v=7AUeeSGBwto') ON DUPLICATE KEY UPDATE name_ko=VALUES(name_ko), name_en=VALUES(name_en), exercise_type=VALUES(exercise_type), primary_muscle=VALUES(primary_muscle), movement_pattern=VALUES(movement_pattern), minimum_experience_level=VALUES(minimum_experience_level), baseline_record_type=VALUES(baseline_record_type), guide=VALUES(guide), video_url=VALUES(video_url);
INSERT INTO exercise (exercise_code, name_ko, name_en, exercise_type, primary_muscle, movement_pattern, minimum_experience_level, baseline_record_type, guide, video_url) VALUES ('EX_BICEPS_ARM_CURL_MACHINE', '암 컬 머신', 'Arm Curl Machine', 'STRENGTH', 'BICEPS', 'ELBOW_FLEXION', 'FIRST_TIME', 'WEIGHT_REPS_SETS', '기계의 회전축에 팔꿈치를 맞추고 상완을 패드에 안정적으로 올려주세요.\n팔꿈치를 굽혀 손잡이를 올린 뒤 천천히 내려주세요.\n어깨가 들리거나 엉덩이가 좌석에서 뜨지 않도록 주의하세요.', 'https://www.youtube.com/watch?v=FA796EywDRo') ON DUPLICATE KEY UPDATE name_ko=VALUES(name_ko), name_en=VALUES(name_en), exercise_type=VALUES(exercise_type), primary_muscle=VALUES(primary_muscle), movement_pattern=VALUES(movement_pattern), minimum_experience_level=VALUES(minimum_experience_level), baseline_record_type=VALUES(baseline_record_type), guide=VALUES(guide), video_url=VALUES(video_url);
INSERT INTO exercise (exercise_code, name_ko, name_en, exercise_type, primary_muscle, movement_pattern, minimum_experience_level, baseline_record_type, guide, video_url) VALUES ('EX_CORE_CRUNCH', '크런치', 'Crunch', 'CORE', 'CORE', 'CORE', 'FIRST_TIME', 'REPS_SETS', '무릎을 굽히고 누워 발바닥을 바닥에 붙여주세요.\n복부에 힘을 주어 어깨를 바닥에서 살짝 들어 올린 뒤 천천히 내려주세요.\n손으로 목을 잡아당기거나 허리까지 크게 일으키지 않도록 주의하세요.', 'https://www.youtube.com/watch?v=pRh_RRnTwwY') ON DUPLICATE KEY UPDATE name_ko=VALUES(name_ko), name_en=VALUES(name_en), exercise_type=VALUES(exercise_type), primary_muscle=VALUES(primary_muscle), movement_pattern=VALUES(movement_pattern), minimum_experience_level=VALUES(minimum_experience_level), baseline_record_type=VALUES(baseline_record_type), guide=VALUES(guide), video_url=VALUES(video_url);
INSERT INTO exercise (exercise_code, name_ko, name_en, exercise_type, primary_muscle, movement_pattern, minimum_experience_level, baseline_record_type, guide, video_url) VALUES ('EX_CORE_LYING_LEG_RAISE', '라잉 레그 레이즈', 'Lying Leg Raise', 'CORE', 'CORE', 'CORE', 'BEGINNER', 'REPS_SETS', '바닥에 누워 다리를 모으고 복부에 힘을 주세요.\n허리가 바닥에서 과하게 뜨지 않는 범위에서 다리를 들어 올렸다가 천천히 내려주세요.\n반동으로 다리를 흔들거나 허리가 꺾이는 높이까지 내리지 않도록 주의하세요.', 'https://www.youtube.com/watch?v=tObWHCnLkKg') ON DUPLICATE KEY UPDATE name_ko=VALUES(name_ko), name_en=VALUES(name_en), exercise_type=VALUES(exercise_type), primary_muscle=VALUES(primary_muscle), movement_pattern=VALUES(movement_pattern), minimum_experience_level=VALUES(minimum_experience_level), baseline_record_type=VALUES(baseline_record_type), guide=VALUES(guide), video_url=VALUES(video_url);
INSERT INTO exercise (exercise_code, name_ko, name_en, exercise_type, primary_muscle, movement_pattern, minimum_experience_level, baseline_record_type, guide, video_url) VALUES ('EX_CORE_HANGING_LEG_RAISE', '행잉 레그 레이즈', 'Hanging Leg Raise', 'CORE', 'CORE', 'CORE', 'INTERMEDIATE', 'REPS_SETS', '철봉을 잡고 어깨를 안정적으로 유지하며 매달려주세요.\n몸통을 흔들지 않고 복부에 힘을 주어 다리를 들어 올린 뒤 천천히 내려주세요.\n반동을 이용하거나 허리를 과하게 젖히지 않도록 주의하세요.', 'https://www.youtube.com/watch?v=puEEqXIrCL4') ON DUPLICATE KEY UPDATE name_ko=VALUES(name_ko), name_en=VALUES(name_en), exercise_type=VALUES(exercise_type), primary_muscle=VALUES(primary_muscle), movement_pattern=VALUES(movement_pattern), minimum_experience_level=VALUES(minimum_experience_level), baseline_record_type=VALUES(baseline_record_type), guide=VALUES(guide), video_url=VALUES(video_url);
INSERT INTO exercise (exercise_code, name_ko, name_en, exercise_type, primary_muscle, movement_pattern, minimum_experience_level, baseline_record_type, guide, video_url) VALUES ('EX_CORE_BICYCLE_CRUNCH', '바이시클 크런치', 'Bicycle Crunch', 'CORE', 'CORE', 'CORE', 'BEGINNER', 'REPS_SETS', '바닥에 누워 양손을 머리 옆에 두고 다리를 들어 올려주세요.\n한쪽 무릎을 당기며 반대쪽 어깨를 그 방향으로 돌리고 좌우를 번갈아 반복하세요.\n손으로 목을 당기거나 빠른 반동으로 움직이지 않도록 주의하세요.', 'https://www.youtube.com/watch?v=tPB6MvOU2aU') ON DUPLICATE KEY UPDATE name_ko=VALUES(name_ko), name_en=VALUES(name_en), exercise_type=VALUES(exercise_type), primary_muscle=VALUES(primary_muscle), movement_pattern=VALUES(movement_pattern), minimum_experience_level=VALUES(minimum_experience_level), baseline_record_type=VALUES(baseline_record_type), guide=VALUES(guide), video_url=VALUES(video_url);
INSERT INTO exercise (exercise_code, name_ko, name_en, exercise_type, primary_muscle, movement_pattern, minimum_experience_level, baseline_record_type, guide, video_url) VALUES ('EX_CORE_BIRD_DOG', '버드독', 'Bird-Dog', 'CORE', 'CORE', 'CORE', 'FIRST_TIME', 'REPS_SETS', '네발기기 자세에서 손은 어깨 아래, 무릎은 골반 아래에 놓아주세요.\n복부에 힘을 주고 한쪽 팔과 반대쪽 다리를 곧게 뻗어주세요.\n골반이 기울거나 허리가 꺾이지 않도록 몸통을 안정적으로 유지해주세요.', 'https://youtu.be/SfjFnlwBwgE?si=SnvR_bkbCFGV-1HL') ON DUPLICATE KEY UPDATE name_ko=VALUES(name_ko), name_en=VALUES(name_en), exercise_type=VALUES(exercise_type), primary_muscle=VALUES(primary_muscle), movement_pattern=VALUES(movement_pattern), minimum_experience_level=VALUES(minimum_experience_level), baseline_record_type=VALUES(baseline_record_type), guide=VALUES(guide), video_url=VALUES(video_url);
INSERT INTO exercise (exercise_code, name_ko, name_en, exercise_type, primary_muscle, movement_pattern, minimum_experience_level, baseline_record_type, guide, video_url) VALUES ('EX_CORE_AB_ROLLOUT', 'AB 롤아웃', 'Ab Roller', 'CORE', 'CORE', 'CORE', 'INTERMEDIATE', 'REPS_SETS', '무릎을 바닥에 대고 롤아웃 휠을 어깨 아래에 놓아주세요.\n복부에 힘을 유지하며 휠을 앞으로 천천히 굴려 몸을 뻗은 뒤 돌아와주세요.\n허리가 아래로 처지거나 과도하게 꺾이지 않도록 주의해주세요.', 'https://youtu.be/OPBzMasp-o0?si=togZoAchbtPSuVC3') ON DUPLICATE KEY UPDATE name_ko=VALUES(name_ko), name_en=VALUES(name_en), exercise_type=VALUES(exercise_type), primary_muscle=VALUES(primary_muscle), movement_pattern=VALUES(movement_pattern), minimum_experience_level=VALUES(minimum_experience_level), baseline_record_type=VALUES(baseline_record_type), guide=VALUES(guide), video_url=VALUES(video_url);
INSERT INTO exercise (exercise_code, name_ko, name_en, exercise_type, primary_muscle, movement_pattern, minimum_experience_level, baseline_record_type, guide, video_url) VALUES ('EX_CORE_DB_SIDE_BEND', '덤벨 사이드 밴드', 'Dumbbell Side Bend', 'CORE', 'CORE', 'CORE', 'BEGINNER', 'WEIGHT_REPS_SETS', '덤벨 하나를 한 손에 들고 발을 어깨너비로 벌려 서주세요.\n덤벨을 든 쪽으로 상체를 천천히 기울였다가 복부와 옆구리에 힘을 주며 돌아와주세요.\n몸통이 앞뒤로 기울거나 골반이 좌우로 움직이지 않도록 주의해주세요.', 'https://youtu.be/8VWROqyuJeg?si=cEnhv_sYK40GSNOI') ON DUPLICATE KEY UPDATE name_ko=VALUES(name_ko), name_en=VALUES(name_en), exercise_type=VALUES(exercise_type), primary_muscle=VALUES(primary_muscle), movement_pattern=VALUES(movement_pattern), minimum_experience_level=VALUES(minimum_experience_level), baseline_record_type=VALUES(baseline_record_type), guide=VALUES(guide), video_url=VALUES(video_url);
INSERT INTO exercise (exercise_code, name_ko, name_en, exercise_type, primary_muscle, movement_pattern, minimum_experience_level, baseline_record_type, guide, video_url) VALUES ('EX_CORE_CABLE_CRUNCH', '케이블 크런치', 'Cable Crunch', 'CORE', 'CORE', 'CORE', 'BEGINNER', 'WEIGHT_REPS_SETS', '케이블 머신 앞에서 무릎을 꿇고 로프 손잡이를 머리 옆에 잡아주세요.\n복부를 수축하며 상체를 아래로 둥글게 말아 내린 뒤 천천히 돌아와주세요.\n팔로 손잡이를 당기거나 엉덩이를 앞뒤로 움직이지 않도록 주의해주세요.', 'https://youtu.be/p0kCQS4T_iA?si=WX3uPS8fC8m6gsTE') ON DUPLICATE KEY UPDATE name_ko=VALUES(name_ko), name_en=VALUES(name_en), exercise_type=VALUES(exercise_type), primary_muscle=VALUES(primary_muscle), movement_pattern=VALUES(movement_pattern), minimum_experience_level=VALUES(minimum_experience_level), baseline_record_type=VALUES(baseline_record_type), guide=VALUES(guide), video_url=VALUES(video_url);
INSERT INTO exercise (exercise_code, name_ko, name_en, exercise_type, primary_muscle, movement_pattern, minimum_experience_level, baseline_record_type, guide, video_url) VALUES ('EX_CORE_HANGING_KNEE_RAISE', '행잉 니 레이즈', 'Hanging Knee Raise', 'CORE', 'CORE', 'CORE', 'INTERMEDIATE', 'REPS_SETS', '철봉을 어깨너비로 잡고 매달려 몸을 안정적으로 유지해주세요.\n복부에 힘을 주고 무릎을 가슴 쪽으로 들어 올린 뒤 천천히 내려주세요.\n몸이 앞뒤로 흔들리거나 반동으로 다리를 들어 올리지 않도록 주의해주세요.', 'https://youtu.be/0-11-eeuIPE?si=SLJ1Q_dhlLsGBauK') ON DUPLICATE KEY UPDATE name_ko=VALUES(name_ko), name_en=VALUES(name_en), exercise_type=VALUES(exercise_type), primary_muscle=VALUES(primary_muscle), movement_pattern=VALUES(movement_pattern), minimum_experience_level=VALUES(minimum_experience_level), baseline_record_type=VALUES(baseline_record_type), guide=VALUES(guide), video_url=VALUES(video_url);
INSERT INTO exercise (exercise_code, name_ko, name_en, exercise_type, primary_muscle, movement_pattern, minimum_experience_level, baseline_record_type, guide, video_url) VALUES ('EX_CORE_DEAD_BUG', '데드 버그', 'Dead Bug', 'CORE', 'CORE', 'CORE', 'FIRST_TIME', 'REPS_SETS', '바닥에 등을 대고 누워 양팔을 천장으로 뻗고 무릎을 90도로 굽혀 들어주세요.\n오른팔과 왼다리를 동시에 천천히 뻗었다가 돌아오고 반대쪽도 반복해주세요.\n허리가 바닥에서 뜨거나 몸통이 흔들리지 않도록 복부에 힘을 유지해주세요.', 'https://www.youtube.com/watch?v=9RK9UUgKIQE') ON DUPLICATE KEY UPDATE name_ko=VALUES(name_ko), name_en=VALUES(name_en), exercise_type=VALUES(exercise_type), primary_muscle=VALUES(primary_muscle), movement_pattern=VALUES(movement_pattern), minimum_experience_level=VALUES(minimum_experience_level), baseline_record_type=VALUES(baseline_record_type), guide=VALUES(guide), video_url=VALUES(video_url);
INSERT INTO exercise (exercise_code, name_ko, name_en, exercise_type, primary_muscle, movement_pattern, minimum_experience_level, baseline_record_type, guide, video_url) VALUES ('EX_CORE_REVERSE_CRUNCH', '리버스 크런치', 'Reverse Crunch', 'CORE', 'CORE', 'CORE', 'BEGINNER', 'REPS_SETS', '바닥에 등을 대고 누워 무릎을 굽히고 양손은 몸 옆에 놓아주세요.\n복부에 힘을 주며 무릎을 가슴 쪽으로 당기고 엉덩이를 살짝 들어 올려주세요.\n다리의 반동을 사용하거나 허리를 과하게 꺾지 말고 천천히 내려주세요.', 'https://www.youtube.com/watch?v=XY8KzdDcMFg') ON DUPLICATE KEY UPDATE name_ko=VALUES(name_ko), name_en=VALUES(name_en), exercise_type=VALUES(exercise_type), primary_muscle=VALUES(primary_muscle), movement_pattern=VALUES(movement_pattern), minimum_experience_level=VALUES(minimum_experience_level), baseline_record_type=VALUES(baseline_record_type), guide=VALUES(guide), video_url=VALUES(video_url);
INSERT INTO exercise (exercise_code, name_ko, name_en, exercise_type, primary_muscle, movement_pattern, minimum_experience_level, baseline_record_type, guide, video_url) VALUES ('EX_CORE_SEATED_KNEE_TUCK', '시티드 니 턱', 'Seated Knee Tuck', 'CORE', 'CORE', 'CORE', 'BEGINNER', 'REPS_SETS', '앉은 상태에서 손으로 바닥을 짚고 다리를 앞으로 뻗어주세요.\n무릎을 가슴 쪽으로 당기면서 상체를 살짝 숙여주세요.\n허리가 과도하게 말리거나 몸이 흔들리지 않도록 천천히 반복해주세요.', 'https://youtu.be/m0LJOpgoio4?si=_yh4N5rCmICGY8w2') ON DUPLICATE KEY UPDATE name_ko=VALUES(name_ko), name_en=VALUES(name_en), exercise_type=VALUES(exercise_type), primary_muscle=VALUES(primary_muscle), movement_pattern=VALUES(movement_pattern), minimum_experience_level=VALUES(minimum_experience_level), baseline_record_type=VALUES(baseline_record_type), guide=VALUES(guide), video_url=VALUES(video_url);
INSERT INTO exercise (exercise_code, name_ko, name_en, exercise_type, primary_muscle, movement_pattern, minimum_experience_level, baseline_record_type, guide, video_url) VALUES ('EX_CORE_HEEL_TOUCH', '힐 터치', 'Heel Touch', 'CORE', 'CORE', 'CORE', 'FIRST_TIME', 'REPS_SETS', '바닥에 누워 무릎을 세우고 발을 바닥에 붙여주세요.\n상체를 살짝 들어 올린 뒤 양옆으로 몸을 기울여 손으로 발뒤꿈치를 번갈아 터치해주세요.\n목에 힘을 주거나 허리가 과도하게 들리지 않도록 복부에 힘을 유지해주세요.', 'https://youtu.be/ofSllPXMVeI?si=SseWI4dLBrwQB3tq') ON DUPLICATE KEY UPDATE name_ko=VALUES(name_ko), name_en=VALUES(name_en), exercise_type=VALUES(exercise_type), primary_muscle=VALUES(primary_muscle), movement_pattern=VALUES(movement_pattern), minimum_experience_level=VALUES(minimum_experience_level), baseline_record_type=VALUES(baseline_record_type), guide=VALUES(guide), video_url=VALUES(video_url);
INSERT INTO exercise (exercise_code, name_ko, name_en, exercise_type, primary_muscle, movement_pattern, minimum_experience_level, baseline_record_type, guide, video_url) VALUES ('EX_CORE_V_UP', '브이 업', 'V-Up', 'CORE', 'CORE', 'CORE', 'INTERMEDIATE', 'REPS_SETS', '바닥에 누워 팔을 머리 위로 뻗고 다리를 곧게 펴주세요.\n복부에 힘을 주며 상체와 다리를 동시에 들어 올려 손으로 발끝을 향해 뻗어주세요.\n반동을 사용하지 말고 허리와 목에 무리가 가지 않는 범위에서 반복해주세요.', 'https://youtu.be/Bt4nDFDRhbw?si=hwb1ODiDgoj5X41Z') ON DUPLICATE KEY UPDATE name_ko=VALUES(name_ko), name_en=VALUES(name_en), exercise_type=VALUES(exercise_type), primary_muscle=VALUES(primary_muscle), movement_pattern=VALUES(movement_pattern), minimum_experience_level=VALUES(minimum_experience_level), baseline_record_type=VALUES(baseline_record_type), guide=VALUES(guide), video_url=VALUES(video_url);
INSERT INTO exercise (exercise_code, name_ko, name_en, exercise_type, primary_muscle, movement_pattern, minimum_experience_level, baseline_record_type, guide, video_url) VALUES ('EX_FULL_BURPEE', '버피 테스트', 'Burpee', 'HIIT', 'FULL_BODY', 'FULL_BODY', 'BEGINNER', 'REPS_SETS', '발을 어깨너비로 벌리고 선 뒤 쪼그려 앉아 양손을 바닥에 짚어주세요.\n두 발을 뒤로 뻗어 플랭크 자세를 만든 뒤 다시 당겨 일어서며 점프해주세요.\n착지할 때 무릎을 부드럽게 굽히고 허리가 꺾이거나 엉덩이가 처지지 않도록 주의해주세요.', 'https://youtu.be/UeVDx20Jbs8?si=4t_w0OyxxHQd42MS') ON DUPLICATE KEY UPDATE name_ko=VALUES(name_ko), name_en=VALUES(name_en), exercise_type=VALUES(exercise_type), primary_muscle=VALUES(primary_muscle), movement_pattern=VALUES(movement_pattern), minimum_experience_level=VALUES(minimum_experience_level), baseline_record_type=VALUES(baseline_record_type), guide=VALUES(guide), video_url=VALUES(video_url);
INSERT INTO exercise (exercise_code, name_ko, name_en, exercise_type, primary_muscle, movement_pattern, minimum_experience_level, baseline_record_type, guide, video_url) VALUES ('EX_FULL_JUMPING_JACK', '팔벌려뛰기', 'Jumping Jack', 'HIIT', 'FULL_BODY', 'FULL_BODY', 'FIRST_TIME', 'REPS_SETS', '발을 모으고 선 상태에서 양팔을 몸 옆에 내려주세요.\n점프하며 다리를 벌리고 양팔을 머리 위로 올린 뒤 다시 모아주세요.\n착지할 때 무릎을 살짝 굽히고 일정한 리듬으로 가볍게 반복해주세요.', 'https://youtu.be/nJeDU7qQIP4?si=LXuo2BgCc5a2vlbc') ON DUPLICATE KEY UPDATE name_ko=VALUES(name_ko), name_en=VALUES(name_en), exercise_type=VALUES(exercise_type), primary_muscle=VALUES(primary_muscle), movement_pattern=VALUES(movement_pattern), minimum_experience_level=VALUES(minimum_experience_level), baseline_record_type=VALUES(baseline_record_type), guide=VALUES(guide), video_url=VALUES(video_url);
INSERT INTO exercise (exercise_code, name_ko, name_en, exercise_type, primary_muscle, movement_pattern, minimum_experience_level, baseline_record_type, guide, video_url) VALUES ('EX_FULL_SQUAT_JUMP', '스쿼트 점프', 'Squat Jump', 'HIIT', 'LEGS_GLUTES', 'SQUAT', 'BEGINNER', 'REPS_SETS', '발을 어깨너비로 벌리고 엉덩이를 뒤로 빼며 스쿼트 자세로 앉아주세요.\n발바닥으로 바닥을 밀어 위로 점프한 뒤 다시 스쿼트 자세로 착지해주세요.\n무릎이 안쪽으로 모이지 않도록 하고 착지 충격을 부드럽게 흡수해주세요.', 'https://youtu.be/SL-reYwCRes?si=QaE-1Huygtcx5N7g') ON DUPLICATE KEY UPDATE name_ko=VALUES(name_ko), name_en=VALUES(name_en), exercise_type=VALUES(exercise_type), primary_muscle=VALUES(primary_muscle), movement_pattern=VALUES(movement_pattern), minimum_experience_level=VALUES(minimum_experience_level), baseline_record_type=VALUES(baseline_record_type), guide=VALUES(guide), video_url=VALUES(video_url);
INSERT INTO exercise (exercise_code, name_ko, name_en, exercise_type, primary_muscle, movement_pattern, minimum_experience_level, baseline_record_type, guide, video_url) VALUES ('EX_FULL_KB_SNATCH', '케틀벨 스내치', 'Kettlebell Snatch', 'HIIT', 'FULL_BODY', 'FULL_BODY', 'ADVANCED', 'WEIGHT_REPS_SETS', '발을 어깨너비로 벌리고 케틀벨을 다리 사이에 둔 채 엉덩이를 뒤로 빼주세요.\n엉덩이와 하체의 힘으로 케틀벨을 위로 끌어 올려 팔을 머리 위로 뻗어주세요.\n허리 힘으로 들어 올리지 말고 손목과 어깨가 꺾이지 않도록 제어해주세요.', 'https://youtu.be/--27yW1Sle0?si=s4HH5QUP1P9iyZVE') ON DUPLICATE KEY UPDATE name_ko=VALUES(name_ko), name_en=VALUES(name_en), exercise_type=VALUES(exercise_type), primary_muscle=VALUES(primary_muscle), movement_pattern=VALUES(movement_pattern), minimum_experience_level=VALUES(minimum_experience_level), baseline_record_type=VALUES(baseline_record_type), guide=VALUES(guide), video_url=VALUES(video_url);
INSERT INTO exercise (exercise_code, name_ko, name_en, exercise_type, primary_muscle, movement_pattern, minimum_experience_level, baseline_record_type, guide, video_url) VALUES ('EX_FULL_KB_CLEAN', '케틀벨 클린', 'Kettlebell Clean', 'HIIT', 'FULL_BODY', 'FULL_BODY', 'INTERMEDIATE', 'WEIGHT_REPS_SETS', '발을 어깨너비로 벌리고 케틀벨을 다리 사이에 둔 채 엉덩이를 뒤로 빼주세요.\n엉덩이와 하체의 힘으로 케틀벨을 위로 끌어 올려 팔꿈치가 몸통 가까이에 오도록 어깨 앞에 안착시켜주세요.\n케틀벨이 손목을 세게 치지 않도록 궤적을 제어하고 허리가 과도하게 꺾이지 않도록 주의해주세요.', 'https://youtu.be/jAmKJulmi14?si=j1oEki45BW9y905K') ON DUPLICATE KEY UPDATE name_ko=VALUES(name_ko), name_en=VALUES(name_en), exercise_type=VALUES(exercise_type), primary_muscle=VALUES(primary_muscle), movement_pattern=VALUES(movement_pattern), minimum_experience_level=VALUES(minimum_experience_level), baseline_record_type=VALUES(baseline_record_type), guide=VALUES(guide), video_url=VALUES(video_url);
INSERT INTO exercise (exercise_code, name_ko, name_en, exercise_type, primary_muscle, movement_pattern, minimum_experience_level, baseline_record_type, guide, video_url) VALUES ('EX_FULL_DB_BURPEE', '덤벨 버피', 'Dumbbell Burpee', 'HIIT', 'FULL_BODY', 'FULL_BODY', 'INTERMEDIATE', 'WEIGHT_REPS_SETS', '양손에 덤벨을 잡고 발을 어깨너비로 벌려 선 뒤 쪼그려 앉아주세요.\n덤벨을 바닥에 짚고 두 발을 뒤로 뻗었다가 다시 당겨 일어서주세요.\n덤벨이 굴러가지 않도록 안정적으로 잡고 허리와 손목에 무리가 가지 않게 움직여주세요.', 'https://youtu.be/Ed69soS-dIM?si=SGLpUKJbQdpwStga') ON DUPLICATE KEY UPDATE name_ko=VALUES(name_ko), name_en=VALUES(name_en), exercise_type=VALUES(exercise_type), primary_muscle=VALUES(primary_muscle), movement_pattern=VALUES(movement_pattern), minimum_experience_level=VALUES(minimum_experience_level), baseline_record_type=VALUES(baseline_record_type), guide=VALUES(guide), video_url=VALUES(video_url);
INSERT INTO exercise (exercise_code, name_ko, name_en, exercise_type, primary_muscle, movement_pattern, minimum_experience_level, baseline_record_type, guide, video_url) VALUES ('EX_CARDIO_JUMP_ROPE', '줄넘기', 'Jump Rope', 'CARDIO', 'CARDIO', 'CARDIO', 'BEGINNER', 'DURATION', '줄의 손잡이를 양손에 잡고 줄이 발 앞을 지나도록 준비해주세요.\n손목을 돌려 줄을 넘기며 발끝으로 가볍게 점프해주세요.\n팔 전체를 크게 휘두르지 말고 무릎을 살짝 굽혀 부드럽게 착지해주세요.', 'https://youtu.be/_yWerNDS2AQ?si=wfbUzft-B9XR0kWJ') ON DUPLICATE KEY UPDATE name_ko=VALUES(name_ko), name_en=VALUES(name_en), exercise_type=VALUES(exercise_type), primary_muscle=VALUES(primary_muscle), movement_pattern=VALUES(movement_pattern), minimum_experience_level=VALUES(minimum_experience_level), baseline_record_type=VALUES(baseline_record_type), guide=VALUES(guide), video_url=VALUES(video_url);
INSERT INTO exercise (exercise_code, name_ko, name_en, exercise_type, primary_muscle, movement_pattern, minimum_experience_level, baseline_record_type, guide, video_url) VALUES ('EX_FULL_STEP_BOX_JUMP', '스텝박스 점프', 'Step-box Jump', 'HIIT', 'LEGS_GLUTES', 'FULL_BODY', 'INTERMEDIATE', 'REPS_SETS', '스텝박스 앞에 발을 어깨너비로 벌리고 서서 무릎과 엉덩이를 살짝 굽혀주세요.\n양발로 바닥을 밀어 박스 위로 점프한 뒤 두 발로 안정적으로 착지해주세요.\n박스 높이는 자신의 능력에 맞게 선택하고 내려올 때는 무리하게 뛰어내리지 마세요.', 'https://youtu.be/5rTFGRGQupI?si=BdkclAdV7HzGHc99') ON DUPLICATE KEY UPDATE name_ko=VALUES(name_ko), name_en=VALUES(name_en), exercise_type=VALUES(exercise_type), primary_muscle=VALUES(primary_muscle), movement_pattern=VALUES(movement_pattern), minimum_experience_level=VALUES(minimum_experience_level), baseline_record_type=VALUES(baseline_record_type), guide=VALUES(guide), video_url=VALUES(video_url);
INSERT INTO exercise (exercise_code, name_ko, name_en, exercise_type, primary_muscle, movement_pattern, minimum_experience_level, baseline_record_type, guide, video_url) VALUES ('EX_CARDIO_TREADMILL', '런닝머신', 'Treadmill', 'CARDIO', 'CARDIO', 'CARDIO', 'FIRST_TIME', 'DURATION', '벨트가 멈춘 상태에서 발판에 올라 손잡이를 잡고 운동을 시작해주세요.\n속도와 경사를 조절하며 시선을 정면에 두고 자연스럽게 걷거나 달려주세요.\n벨트 위에서 갑자기 멈추거나 발을 옆으로 내딛지 말고 속도를 낮춘 뒤 안전하게 내려주세요.', 'https://youtu.be/l1hr3hk7tmE?si=wEL2RK54AjaPbfnF') ON DUPLICATE KEY UPDATE name_ko=VALUES(name_ko), name_en=VALUES(name_en), exercise_type=VALUES(exercise_type), primary_muscle=VALUES(primary_muscle), movement_pattern=VALUES(movement_pattern), minimum_experience_level=VALUES(minimum_experience_level), baseline_record_type=VALUES(baseline_record_type), guide=VALUES(guide), video_url=VALUES(video_url);
INSERT INTO exercise (exercise_code, name_ko, name_en, exercise_type, primary_muscle, movement_pattern, minimum_experience_level, baseline_record_type, guide, video_url) VALUES ('EX_CARDIO_STAIRMASTER', '스테어마스터', 'StairMaster', 'CARDIO', 'CARDIO', 'CARDIO', 'FIRST_TIME', 'DURATION', '기구에 올라 손잡이를 가볍게 잡고 발을 계단 중앙에 올려주세요.\n계단의 움직임에 맞춰 한 발씩 번갈아 디디며 일정한 속도로 올라가주세요.\n손잡이에 체중을 과도하게 싣거나 상체를 숙이지 말고 발을 안정적으로 디뎌주세요.', 'https://youtu.be/zeokcdKDUNY?si=XbitxmB59zcpf9xJ') ON DUPLICATE KEY UPDATE name_ko=VALUES(name_ko), name_en=VALUES(name_en), exercise_type=VALUES(exercise_type), primary_muscle=VALUES(primary_muscle), movement_pattern=VALUES(movement_pattern), minimum_experience_level=VALUES(minimum_experience_level), baseline_record_type=VALUES(baseline_record_type), guide=VALUES(guide), video_url=VALUES(video_url);
INSERT INTO exercise (exercise_code, name_ko, name_en, exercise_type, primary_muscle, movement_pattern, minimum_experience_level, baseline_record_type, guide, video_url) VALUES ('EX_CARDIO_ROWING_MACHINE', '로잉 머신', 'Rowing Machine', 'CARDIO', 'CARDIO', 'CARDIO', 'BEGINNER', 'DURATION', '발을 발판에 고정하고 무릎을 굽힌 채 손잡이를 잡아주세요.\n다리로 먼저 밀어낸 뒤 상체를 약간 뒤로 기울이고 팔꿈치를 당겨 손잡이를 복부 쪽으로 가져와주세요.\n돌아갈 때는 팔을 먼저 뻗고 상체와 무릎을 순서대로 움직이며 허리를 과도하게 굽히지 마세요.', 'https://youtu.be/q5QHmLeBpbY?si=c5K8aWf_mNPE0bv0') ON DUPLICATE KEY UPDATE name_ko=VALUES(name_ko), name_en=VALUES(name_en), exercise_type=VALUES(exercise_type), primary_muscle=VALUES(primary_muscle), movement_pattern=VALUES(movement_pattern), minimum_experience_level=VALUES(minimum_experience_level), baseline_record_type=VALUES(baseline_record_type), guide=VALUES(guide), video_url=VALUES(video_url);
INSERT INTO exercise (exercise_code, name_ko, name_en, exercise_type, primary_muscle, movement_pattern, minimum_experience_level, baseline_record_type, guide, video_url) VALUES ('EX_CARDIO_STATIONARY_BIKE', '실내 자전거', 'Stationary Bike', 'CARDIO', 'CARDIO', 'CARDIO', 'FIRST_TIME', 'DURATION', '안장 높이를 조절해 페달이 가장 아래에 있을 때 무릎이 살짝 굽혀지도록 맞춰주세요.\n페달을 일정한 리듬으로 밟으며 상체를 안정적으로 유지해주세요.\n무릎이 안쪽이나 바깥쪽으로 쏠리지 않도록 하고 허리와 어깨에 불필요한 긴장을 주지 마세요.', 'https://youtu.be/0042TOjFRMc?si=llGiY6jS7Xwt0gBo') ON DUPLICATE KEY UPDATE name_ko=VALUES(name_ko), name_en=VALUES(name_en), exercise_type=VALUES(exercise_type), primary_muscle=VALUES(primary_muscle), movement_pattern=VALUES(movement_pattern), minimum_experience_level=VALUES(minimum_experience_level), baseline_record_type=VALUES(baseline_record_type), guide=VALUES(guide), video_url=VALUES(video_url);
INSERT INTO exercise (exercise_code, name_ko, name_en, exercise_type, primary_muscle, movement_pattern, minimum_experience_level, baseline_record_type, guide, video_url) VALUES ('EX_CARDIO_ELLIPTICAL', '엘립티컬', 'Elliptical', 'CARDIO', 'CARDIO', 'CARDIO', 'FIRST_TIME', 'DURATION', '발판에 양발을 올리고 손잡이를 잡은 뒤 몸의 균형을 잡아주세요.\n발판을 번갈아 밀면서 손잡이를 자연스럽게 움직여 일정한 리듬을 유지해주세요.\n발뒤꿈치가 과도하게 들리거나 무릎이 안쪽으로 모이지 않도록 주의해주세요.', 'https://youtu.be/gXjUELEs-Po?si=LGpO8jDNHQWKJxTE') ON DUPLICATE KEY UPDATE name_ko=VALUES(name_ko), name_en=VALUES(name_en), exercise_type=VALUES(exercise_type), primary_muscle=VALUES(primary_muscle), movement_pattern=VALUES(movement_pattern), minimum_experience_level=VALUES(minimum_experience_level), baseline_record_type=VALUES(baseline_record_type), guide=VALUES(guide), video_url=VALUES(video_url);
INSERT INTO exercise (exercise_code, name_ko, name_en, exercise_type, primary_muscle, movement_pattern, minimum_experience_level, baseline_record_type, guide, video_url) VALUES ('EX_OUTDOOR_WALK', '야외 걷기', 'Outdoor Walking', 'CARDIO', 'CARDIO', 'CARDIO', 'FIRST_TIME', 'DURATION', '시선을 정면에 두고 허리를 곧게 편 상태로 자연스럽게 걸어주세요.\n팔을 가볍게 흔들며 보폭과 속도를 일정하게 유지해주세요.\n발뒤꿈치부터 부드럽게 디디고 주변 보행자와 장애물을 확인해주세요.', 'https://youtu.be/b5rjBeKGBjI?si=rDZGkaKfHO7CpLPM') ON DUPLICATE KEY UPDATE name_ko=VALUES(name_ko), name_en=VALUES(name_en), exercise_type=VALUES(exercise_type), primary_muscle=VALUES(primary_muscle), movement_pattern=VALUES(movement_pattern), minimum_experience_level=VALUES(minimum_experience_level), baseline_record_type=VALUES(baseline_record_type), guide=VALUES(guide), video_url=VALUES(video_url);
INSERT INTO exercise (exercise_code, name_ko, name_en, exercise_type, primary_muscle, movement_pattern, minimum_experience_level, baseline_record_type, guide, video_url) VALUES ('EX_OUTDOOR_RUN', '야외 러닝', 'Outdoor Running', 'CARDIO', 'CARDIO', 'CARDIO', 'BEGINNER', 'DURATION', '상체를 곧게 세우고 팔꿈치를 자연스럽게 굽힌 상태로 달려주세요.\n보폭을 무리하게 늘리지 말고 일정한 호흡과 리듬을 유지해주세요.\n발을 몸의 무게중심 가까이에 착지하고 주변 차량과 노면 상태를 확인해주세요.', 'https://youtu.be/Ggbm_coe5uM?si=kUr79wRrAysycaty') ON DUPLICATE KEY UPDATE name_ko=VALUES(name_ko), name_en=VALUES(name_en), exercise_type=VALUES(exercise_type), primary_muscle=VALUES(primary_muscle), movement_pattern=VALUES(movement_pattern), minimum_experience_level=VALUES(minimum_experience_level), baseline_record_type=VALUES(baseline_record_type), guide=VALUES(guide), video_url=VALUES(video_url);
INSERT INTO exercise (exercise_code, name_ko, name_en, exercise_type, primary_muscle, movement_pattern, minimum_experience_level, baseline_record_type, guide, video_url) VALUES ('EX_OUTDOOR_CYCLING', '야외 자전거', 'Outdoor Cycling', 'CARDIO', 'CARDIO', 'CARDIO', 'BEGINNER', 'DURATION', '안장과 핸들 높이를 조절하고 헬멧을 착용한 뒤 출발해주세요.\n상체를 안정적으로 유지하며 페달을 일정한 리듬으로 밟아주세요.\n교통 신호와 주변 차량을 확인하고 방향을 바꾸거나 정지할 때는 미리 신호를 보내주세요.', 'https://youtu.be/oeCNnStU_qw?si=DV1RTJcbigVMrt2M') ON DUPLICATE KEY UPDATE name_ko=VALUES(name_ko), name_en=VALUES(name_en), exercise_type=VALUES(exercise_type), primary_muscle=VALUES(primary_muscle), movement_pattern=VALUES(movement_pattern), minimum_experience_level=VALUES(minimum_experience_level), baseline_record_type=VALUES(baseline_record_type), guide=VALUES(guide), video_url=VALUES(video_url);
